    "id": "cd4ba9d2-8d52-5abc-b72d-ee190e90ff69", "type": "c1_mor_determinants", "sort_order": 3,
    "title": "Determinants: article, lo neutre i possessius", "name": "Article davant d'infinitiu, presència i absència d'article, alternatives a lo abstractiu i intensiu, i ús dels possessius",
    "content": "L'ús de l'article davant de l'infinitiu i la restricció de la substantivació, la presència i l'absència d'article, l'article neutre amb valor abstractiu i intensiu, els modismes amb lo interferits i les seues alternatives, la construcció al més + adverbi + possible, i l'ús i l'abús dels possessius, també referits a inanimats (3.2.2).", "icon": "🔖", "color": "#EDE7F6",
    "exercises": [
      {"q": "Quina frase és adequada en un registre formal?", "o": ["Saber això m'alegra molt.", "El saber això m'alegra molt.", "Lo saber això m'alegra molt."], "e": "Davant d'un infinitiu no lexicalitzat s'omet l'article: Saber això m'alegra molt."},
      {"q": "Quina frase evita la substantivació de l'infinitiu amb article?", "o": ["Conéixer bé diverses llengües l'ha ajudat a trobar treball.", "El conéixer bé diverses llengües l'ha ajudat a trobar treball.", "Lo conéixer bé diverses llengües l'ha ajudat a trobar treball."], "e": "Convé evitar l'article davant d'un infinitiu amb complements verbals; s'usa l'infinitiu sol."},
      {"q": "En quin cas l'article davant de l'infinitiu és plenament correcte?", "o": ["el despertar de les passions", "el fumar en llocs públics", "el llegir molts llibres"], "e": "Només admeten plenament l'article els infinitius substantivats: el dinar, el despertar, el saber."},
      {"q": "«No té ___ necessaris per al treball que li han encomanat.»", "o": ["els sabers", "els saber", "lo saber"], "e": "Saber s'ha substantivat i, com a nom, admet el plural: els sabers."},
      {"q": "«___ vages a visitar-lo li farà bé.»", "o": ["Que", "El que", "Lo que"], "e": "Davant d'una oració subordinada substantiva no s'usa l'article: Que vages a visitar-lo li farà bé."},
      {"q": "«___ encara no haja dit res és un bon senyal.»", "o": ["El fet que", "Lo que", "El que"], "e": "Si cal un element davant de la subordinada, s'usa una fórmula com el fet que."},
      {"q": "«Ajuda'm a ___, que ja dinem.»", "o": ["parar taula", "posar la mesa", "parar el taula"], "e": "La locució genuïna és parar taula, sense article."},
      {"q": "«___ que ve anirem al cine.»", "o": ["Divendres", "El divendres", "Lo divendres"], "e": "Amb dies de la setmana que indiquen immediatesa s'omet l'article: divendres que ve, dilluns passat."},
      {"q": "«Anirem a la platja ___.»", "o": ["el pròxim diumenge", "pròxim diumenge", "lo pròxim diumenge"], "e": "Si el dia de la setmana va precedit d'un adjectiu, cal l'article: el pròxim diumenge."},
      {"q": "«La reunió va quedar fixada per a ___.»", "o": ["el dijous 29 de maig", "dijous de 29 de maig", "lo dijous 29 de maig"], "e": "Quan es fa referència a un dia concret amb data, el dia de la setmana porta article: el dijous 29 de maig."},
      {"q": "«___ va a classe de piano, durant tot el curs.»", "o": ["Els dimarts", "Dimarts", "A dimarts"], "e": "Per a indicar freqüència s'usa l'article, en singular o en plural: el dimarts o els dimarts."},
      {"q": "«Anirem al cementeri ___.»", "o": ["el dia de Tots Sants", "el dia dels Tots Sants", "el dia de los Santos"], "e": "La festivitat es diu Tots Sants, sense article: el dia de Tots Sants."},
      {"q": "«Ja s'acosta ___ i encara no hem comprat els regals.»", "o": ["Nadal", "la Nadal", "les Nadals"], "e": "El nom de la festa s'usa sense article i és masculí: Ja s'acosta Nadal; les festes de Nadal."},
      {"q": "«___ arribarà tard a la reunió.»", "o": ["Vicenta", "Na Vicenta", "La Vicenta"], "e": "En valencià, els noms propis de persona s'usen generalment sense article."},
      {"q": "«Treballa en una fàbrica de ___.»", "o": ["la Vall d'Uixó", "Vall d'Uixó", "el Vall d'Uixó"], "e": "Alguns topònims porten l'article per tradició: la Vall d'Uixó, l'Alcora, el Campello."},
      {"q": "«Han viatjat ___ per a vore el desert.»", "o": ["al Marroc", "a Marroc", "a el Marroc"], "e": "El Marroc porta article obligatòriament, que es contrau amb la preposició: al Marroc."},
      {"q": "Quina és l'alternativa formal a «Lo que em dius em sorprén»?", "o": ["Això que em dius em sorprén.", "Lo qual em dius em sorprén.", "Lo que tu em dius em sorprén."], "e": "En els registres formals, lo que es substituïx per el que, això que, açò que o allò que."},
      {"q": "«Té prou diners, però ___ és que no se'ls sap administrar.»", "o": ["el cas", "lo que passa", "lo cas"], "e": "Lo que passa és col·loquial i calcat; en registre formal: el cas és que."},
      {"q": "Quina és l'alternativa formal a «Lo cert és que ho va fer ell»?", "o": ["La veritat és que ho va fer ell.", "Lo verdader és que ho va fer ell.", "Lo cert és que ho va fer ell."], "e": "Lo cert es reemplaça per la veritat o el cert."},
      {"q": "Quina és l'alternativa formal a «Lo lleig i lo bell són relatius»?", "o": ["La lletjor i la bellesa són relatives.", "Lo lleig i el bell són relatius.", "El lleig i lo bell són relatius."], "e": "Amb valor abstractiu, sovint el millor recurs és un substantiu abstracte: la lletjor, la bellesa."},
      {"q": "Com s'ha de dir «No saps lo bé que treballen» en un registre formal?", "o": ["No saps com treballen de bé.", "No saps el bé que treballen.", "No saps lo bé que treballen."], "e": "El lo intensiu no és acceptable en cap context; s'usa que o com: com treballen de bé."},
      {"q": "Com s'ha de dir «Amb lo bonic que és, i no para de plorar!»?", "o": ["Tan bonic que és, i no para de plorar!", "Amb el bonic que és, i no para de plorar!", "Amb lo bonic que és, i no para de plorar!"], "e": "El valor intensiu s'expressa amb tan... que (o com): Tan bonic que és!"},
      {"q": "«No et pots ni imaginar ___ que ens ho hem passat.»", "o": ["que bé", "lo bé", "el bé"], "e": "Per al valor intensiu s'usa que o com: que bé que ens ho hem passat."},
      {"q": "«El projecte encara no està ___ madur.»", "o": ["prou", "lo suficientment", "el suficientment"], "e": "Lo suficientment és un calc; en valencià: prou madur."},
      {"q": "«Envia-m'ho ___ prompte possible.»", "o": ["al més", "lo més", "a lo més"], "e": "La construcció genuïna és al més + adverbi + possible: al més prompte possible."},
      {"q": "Quina frase és correcta?", "o": ["Vine com més prompte millor.", "Vine a lo més prompte possible.", "Vine lo més prompte possible."], "e": "Alternatives correctes: com més prompte millor, tan prompte com pugues o al més prompte possible."},
      {"q": "Quina és l'alternativa genuïna a «A lo millor vindrà en el tren de les deu»?", "o": ["Potser vindrà en el tren de les deu.", "A lo mejor vindrà en el tren de les deu.", "Al millor vindrà en el tren de les deu."], "e": "A lo millor és un modisme calcat; s'usa potser, tal vegada o a la millor."},
      {"q": "«___, sol ser molt puntual.»", "o": ["Generalment", "Per lo general", "Pel general"], "e": "Per lo general és un calc; en valencià: generalment."},
      {"q": "«Li agrada fer les coses ___.»", "o": ["en gran", "a lo gran", "al gran"], "e": "A lo gran és un modisme interferit; s'usa en gran (o viure regaladament, a cor què vols)."},
      {"q": "«Va callar, ___ és molt significatiu.»", "o": ["la qual cosa", "lo qual", "el qual"], "e": "Lo qual s'ha de substituir per la qual cosa o cosa que."},
      {"q": "«Es van casar ___.»", "o": ["pel civil", "per lo civil", "per el civil"], "e": "Davant d'adjectiu substantivat s'usa l'article el, que es contrau: pel civil."},
      {"q": "«Posa'm ___ de sempre: un entrepà de pernil i formatge.»", "o": ["el mateix", "lo", "lo mateix"], "e": "Lo de sempre es reformula: el mateix de sempre (o la història de sempre, segons el context)."},
      {"q": "Quina frase evita l'ús superflu del possessiu?", "o": ["Renta't les mans abans de dinar.", "Renta't les teues mans abans de dinar.", "Renta't tes mans abans de dinar."], "e": "Quan la relació de possessió es deduïx del context, n'hi ha prou amb l'article: Renta't les mans."},
      {"q": "«Anava darrere ___.» (d'ell)", "o": ["seu", "de seu", "el seu"], "e": "En locucions sense article, el possessiu es posposa: darrere seu, prop nostre."},
      {"q": "«Estaven en contra ___.» (de vosaltres)", "o": ["vostra", "de vostre", "el vostre"], "e": "Amb contra s'usa habitualment la forma femenina: en contra vostra."},
      {"q": "En registre formal, quina és la solució preferible quan el posseïdor és inanimat?", "o": ["Este llibre és molt bo; en conec l'autor.", "Este llibre és molt bo; conec el seu autor.", "Este llibre és molt bo; li conec l'autor."], "e": "Amb posseïdors inanimats, la llengua formal preferix el pronom en (+ article) al possessiu: en conec l'autor."},
      {"q": "En un registre molt formal, quin possessiu pot expressar 'la proposta d'ells'?", "o": ["llur proposta", "sa proposta", "la sua proposta"], "e": "Llur (llurs) és un possessiu de tercera persona per a diversos posseïdors, propi de registres molt formals."},
      {"q": "Escriu la paraula que falta (sense «lo»): «Ho faré ___ ràpid com puga.»", "a": ["tan"], "e": "Lo més ràpid possible → tan ràpid com puga."},
      {"q": "Escriu l'alternativa a «per lo tant»: «___, et toca substituir-lo a tu.»", "a": ["Per tant", "per tant"], "e": "Per lo tant és un calc; la forma correcta és per tant."},
      {"q": "Escriu l'alternativa a «en lo successiu»: «___, no vull més excuses.»", "a": ["D'ara en avant", "d'ara en avant", "D'ara endavant", "d'ara endavant"], "e": "En lo successiu es reemplaça per d'ara en avant."},
      {"q": "Escriu l'alternativa a «per lo menys»: «___, ha demanat disculpes.»", "a": ["Almenys", "almenys"], "e": "Per lo menys és un calc; la forma genuïna és almenys, en una sola paraula."},
      {"q": "Escriu l'alternativa a «per lo vist»: «___, és un fora de sèrie.»", "a": ["Segons sembla", "segons sembla", "Pel que es veu", "pel que es veu", "Pel que sembla", "pel que sembla"], "e": "Per lo vist és un calc; s'usa segons sembla o pel que es veu."},
      {"q": "Escriu el pronom que evita el possessiu: «Vam entrar al museu, però només ___ vam visitar una part.»", "a": ["en"], "e": "Amb un posseïdor inanimat (el museu) s'usa en: en vam visitar una part."},
      {"q": "Escriu el possessiu: «Ho ha fet per culpa ___.» (d'ella)", "a": ["seua"], "e": "Quan la locució conté un nom femení, el possessiu va en femení: per culpa seua."},
      {"q": "Escriu l'article: «___ dinar de Nadal serà a casa dels avis.»", "a": ["el", "El"], "e": "Dinar és un infinitiu lexicalitzat com a substantiu i admet l'article: el dinar."}
    ]
  },
  {
    "id": "39bb7c10-632e-5cb5-abce-4f0d1f7caa4c", "type": "c1_mor_pronoms_febles", "sort_order": 4,
    "title": "Pronoms febles: en i hi en totes les funcions", "name": "En i hi com a complement del nom, subjecte i complement de règim, se davant de [s] i usos lexicalitzats",
    "content": "L'ús dels pronoms febles en funció de complement del nom, de subjecte i de complement de règim verbal, el pronom se davant de verbs començats per [s], els pronoms en i hi quan són gramaticalment necessaris i els usos lexicalitzats de en i hi (me'n vaig, vine-te'n, no m'hi veig) (3.2.2).", "icon": "🧲", "color": "#E1BEE7",
    "exercises": [
      {"q": "«Vicent consulta la taula de preus.» Quina pronominalització del complement del nom és correcta?", "o": ["Vicent en consulta la taula.", "Vicent hi consulta la taula.", "Vicent la consulta de preus."], "e": "El complement del nom introduït per de (de preus) es pronominalitza amb en: en consulta la taula."},
      {"q": "«Vam entrar al museu, però només ___ vam visitar una part.»", "o": ["en", "hi", "el"], "e": "En representa el complement del nom part (una part del museu)."},
      {"q": "«D'aquell diccionari, només ___ queda un exemplar.»", "o": ["me'n", "me'l", "m'hi"], "e": "'n = d'aquell diccionari: complement de la part d'un conjunt (un exemplar del diccionari)."},
      {"q": "«—Han arribat ja els convidats? —Només ___ dos.»", "o": ["n'han arribat", "han arribat", "els han arribat"], "e": "Amb un subjecte posposat indefinit o quantificat, el nom es pronominalitza amb en i es manté el quantificador: n'han arribat dos."},
      {"q": "«—Hi havia molta gent a la festa? —___ moltíssima.»", "o": ["N'hi havia", "Hi havia", "La hi havia"], "e": "Gent, quantificat (moltíssima), es pronominalitza amb en; hi és part d'haver-hi: n'hi havia."},
      {"q": "Quina funció fa «en» en «—Han vingut els alumnes? —Només n'han vingut tres»?", "o": ["subjecte posposat", "complement directe", "complement de règim"], "e": "Alumnes és el subjecte de vindre; com que va quantificat i posposat, es pronominalitza amb en."},
      {"q": "«—Parlareu de les retallades en l'assemblea? —Sí, ___ parlarem.»", "o": ["en", "hi", "ho"], "e": "Parlar de: el complement de règim introduït per de es pronominalitza amb en."},
      {"q": "«Havia d'arreplegar el xiquet, però no me'n vaig recordar.» Quina funció fa «'n»?", "o": ["complement de règim (d'arreplegar el xiquet)", "complement directe", "complement circumstancial de lloc"], "e": "Recordar-se de: el complement de règim amb de es pronominalitza amb en."},
      {"q": "«Li vaig dir que em sentia malament i ___ va burlar.»", "o": ["se'n", "s'hi", "es"], "e": "Burlar-se de: 'n = del fet que em sentia malament (complement de règim amb de)."},
      {"q": "«Li van oferir una compensació, però ___ va renunciar.»", "o": ["hi", "en", "la"], "e": "Renunciar a: el complement de règim introduït per una preposició diferent de de es pronominalitza amb hi."},
      {"q": "«—Has pensat en la possibilitat de canviar de feina? —Sí, ___ he pensat molt.»", "o": ["hi", "n'", "l'"], "e": "Pensar en: complement de règim amb en → hi."},
      {"q": "«A la seua manera de parlar, no m'___ acostumaré mai.»", "o": ["hi", "en", "ho"], "e": "Acostumar-se a: hi reprén el complement dislocat a la seua manera de parlar."},
      {"q": "«S'ha comprat un ordinador i ___ està molt content.»", "o": ["n'", "hi", "l'"], "e": "Content de: el complement de l'adjectiu atribut introduït per de es pronominalitza amb en."},
      {"q": "«Han promés noves inversions.» Quina continuació és la més adequada en registre formal?", "o": ["Tots hi confien per a millorar la productivitat.", "Tots confien en elles per a millorar la productivitat.", "Tots en confien per a millorar la productivitat."], "e": "Per a coses, darrere de preposició, es preferixen els febles en i hi al pronom fort: confiar en → hi confien."},
      {"q": "«Ja he vist el reportatge.» Quina continuació és la més adequada en registre formal?", "o": ["No cal que me'n parles.", "No cal que em parles d'ell.", "No cal que m'hi parles."], "e": "Per a referir-se a coses es preferix en (de + cosa) al pronom fort: me'n parles."},
      {"q": "«L'acte ___ celebrarà dissabte a la plaça.» (forma recomanada)", "o": ["se", "es", "s'"], "e": "Davant de verb començat pel so [s] se sol usar la forma plena se per a evitar l'assimilació: se celebrarà."},
      {"q": "«Encara no ___ sap qui guanyarà el premi.» (forma recomanada)", "o": ["se", "es", "s'"], "e": "Davant de [s], forma plena: no se sap res encara."},
      {"q": "«L'exposició ___ inaugurarà demà.»", "o": ["s'", "se", "es"], "e": "Davant de verb començat per vocal, el pronom pren la forma elidida: s'inaugurarà."},
      {"q": "«—Vols més sopa? —Sí, ___ vull més.»", "o": ["en", "la", "Ø (vull més)"], "e": "Si el quantificador (més) apareix sense el nom, cal en: en vull més."},
      {"q": "«—Quants germans tens? —___ tres.»", "o": ["En tinc", "Tinc", "Els tinc"], "e": "Amb un numeral sense nom, el nom elidit es representa amb en: en tinc tres."},
      {"q": "Quina frase sobre la presència de persones és correcta?", "o": ["No hi havia ningú a la sala.", "No havia ningú a la sala.", "No n'havia ningú a la sala."], "e": "El verb existencial és haver-hi: el pronom hi és obligatori (no hi havia ningú)."},
      {"q": "Quina forma del verb existencial és correcta?", "o": ["Hi ha moltes possibilitats d'èxit.", "Ha moltes possibilitats d'èxit.", "N'ha moltes possibilitats d'èxit."], "e": "Haver-hi porta hi lexicalitzat: hi ha, hi havia, hi haurà."},
      {"q": "«—Has comprat pa? —No, no ___ he comprat.»", "o": ["n'", "l'", "hi"], "e": "Pa sense determinant (indefinit) es pronominalitza amb en."},
      {"q": "«—Has comprat el pa? —Sí, ja ___ he comprat.»", "o": ["l'", "n'", "hi"], "e": "El pa és definit: es pronominalitza amb el pronom acusatiu (l'), no amb en."},
      {"q": "«Sense les ulleres no ___ veig.» (no puc veure bé)", "o": ["m'hi", "me'n", "em"], "e": "Veure-s'hi ('tindre vista') porta hi lexicalitzat: no m'hi veig."},
      {"q": "«Amb este vestit tan modern no ___ trobe.» (no em sent còmode)", "o": ["m'hi", "me'n", "m'ho"], "e": "Trobar-s'hi ('sentir-se bé') porta hi lexicalitzat."},
      {"q": "«És molt tard: ___ vaig a casa.»", "o": ["me'n", "em", "m'hi"], "e": "Anar-se'n porta en lexicalitzat: me'n vaig, te'n vas, se'n va."},
      {"q": "«___ al teatre amb nosaltres!» (vindre-se'n, tu)", "o": ["Vine-te'n", "Vine't", "Vine-te-hi"], "e": "Vindre-se'n en imperatiu: vine + te + en → vine-te'n."},
      {"q": "«Tan bon punt ho va saber, ___ va vindre corrents.»", "o": ["se'n", "s'hi", "es"], "e": "Vindre-se'n: verb de desplaçament amb en lexicalitzat."},
      {"q": "«La xiqueta ja ___ ha pujat a casa.»", "o": ["se n'", "se'n", "s'hi"], "e": "Pujar-se'n: es + en davant de vocal → se n'ha pujat (l'apòstrof tan a la dreta com siga possible)."},
      {"q": "«Això no ___ val: has fet trampa!»", "o": ["s'hi", "se'n", "es"], "e": "No s'hi val és una frase feta amb hi lexicalitzat."},
      {"q": "«D'arròs, no ___ vull més.»", "o": ["en", "l'", "hi"], "e": "El nom dislocat amb de es reprén amb en: d'arròs, no en vull més."},
      {"q": "Quina dislocació a la dreta és correcta?", "o": ["No en vull més, d'arròs.", "No en vull més, arròs.", "No vull més, d'arròs."], "e": "En la dislocació a la dreta d'un nom representat per en, la preposició de és obligatòria, i també el pronom en."},
      {"q": "«Vas a la plaça o ___ vens?»", "o": ["en", "hi", "la"], "e": "Vindre de (un lloc): el complement d'origen es pronominalitza amb en."},
      {"q": "«Fa anys que viuen a Ador i encara ___ viuen.»", "o": ["hi", "n'", "la"], "e": "Viure en un lloc: el complement locatiu seleccionat pel verb es pronominalitza amb hi."},
      {"q": "Escriu el pronom: «—Queden entrades per al concert? —Sí, ___ queden poques.»", "a": ["en"], "e": "Subjecte posposat quantificat (poques entrades) → en queden poques."},
      {"q": "Escriu el pronom: «No ___ havia ningú a l'oficina.»", "a": ["hi"], "e": "Haver-hi: no hi havia ningú."},
      {"q": "Escriu la forma recomanada del pronom: «La reunió ___ suspendrà si no hi ha quòrum.»", "a": ["se"], "e": "Davant de [s], forma plena se: se suspendrà."},
      {"q": "Escriu el pronom: «Ja és tard; ___ vaig a dormir.»", "a": ["me'n"], "e": "Anar-se'n: me'n vaig."},
      {"q": "Escriu l'imperatiu de vindre-se'n per a tu: «___ amb mi al mercat!»", "a": ["vine-te'n"], "e": "Vine + te + en → vine-te'n."},
      {"q": "Escriu el pronom: «D'eixe assumpte, ja ___ parlarem demà.»", "a": ["en"], "e": "Parlar d'eixe assumpte → en parlarem."},
      {"q": "Escriu el pronom: «M'agradaria participar en el concurs, però no m'___ atrevisc.»", "a": ["hi"], "e": "Atrevir-se a (participar) → m'hi atrevisc."},
      {"q": "Escriu el pronom: «No em queden camises negres, però sí que ___ tinc de grises.»", "a": ["en"], "e": "En substituïx el nom (camises) i l'adjectiu s'introduïx amb de: en tinc de grises."},
      {"q": "Escriu el pronom: «De la novel·la que em regalares, només me ___ he llegit uns quants capítols.» (amb apòstrof)", "a": ["n'"], "e": "Me n'he llegit: en = de la novel·la (part d'un conjunt)."},
      {"q": "Escriu els pronoms d'anar-se'n (nosaltres): «Ahir ___ vam anar abans de les deu.»", "a": ["ens en"], "e": "Anar-se'n, nosaltres, davant de consonant: ens en vam anar."}
    ]
  },
  {
    "id": "f7ffe732-3093-53e0-8bcb-292b799431f0", "type": "c1_mor_combinacions", "sort_order": 5,
    "title": "Combinacions, pleonasmes i concordança del participi", "name": "Combinacions formals, col·loquials i interferides, duplicacions acceptables i no admeses, i concordança amb els acusatius",
    "content": "Les combinacions de pronoms febles pròpies dels registres formals enfront de les col·loquials o interferides (li ho vaig dir), els usos pleonàstics acceptables (li ho vaig dir a ell) i no admesos (*n'hi ha poc de pa) i la concordança del participi amb els pronoms acusatius de tercera persona (3.2.2).", "icon": "🔗", "color": "#FFE0B2",
    "exercises": [
      {"q": "«Li vaig dir que no vindria.» Quina pronominalització és correcta?", "o": ["Li ho vaig dir.", "Li'l vaig dir.", "Se'l vaig dir."], "e": "Una oració completiva es pronominalitza amb el neutre ho: li + ho → li ho."},
      {"q": "«—Saps que han tancat la fàbrica? —Sí, ja ___ han dit.»", "o": ["m'ho", "me l'", "me la"], "e": "Ho reprén tota l'oració (que han tancat la fàbrica); davant de ho, em pren la forma elidida: m'ho."},
      {"q": "«He donat el regal a ma mare.» Quina pronominalització és correcta?", "o": ["Li l'he donat.", "Se l'he donat.", "Li ho he donat."], "e": "Datiu li + acusatiu el (el regal) davant de vocal: li l'he donat. Se només és reflexiu; usar-lo com a datiu és una interferència del castellà."},
      {"q": "Quina variant de «Li l'he donat» és pròpia dels parlars valencians septentrionals i de la resta de l'àmbit?", "o": ["L'hi he donat.", "Se l'he donat.", "Li hi he donat."], "e": "En eixos parlars, li es convertix en hi davant dels acusatius de tercera persona i es posposa: l'hi, la hi."},
      {"q": "«Tornaré la clau a la veïna.» Quina pronominalització és correcta?", "o": ["Li la tornaré.", "Se la tornaré.", "La li tornaré."], "e": "Li + la davant de consonant: li la. L'orde és fix (datiu davant d'acusatiu); la variant septentrional és la hi."},
      {"q": "Quin orde dels pronoms és adequat en registre formal?", "o": ["Se li ha trencat el got.", "Li s'ha trencat el got.", "Li se ha trencat el got."], "e": "L'orde és se + li. Posposar se a li (li s'ha trencat) és habitual col·loquialment, però no és acceptable en registres formals."},
      {"q": "«___ ha fet tard i he perdut el tren.»", "o": ["Se m'", "Me s'", "Se'm"], "e": "Se precedix els pronoms de primera persona: se + me davant de vocal → se m'ha fet tard."},
      {"q": "«___ ha espatlat el cotxe en plena autovia.» (a nosaltres)", "o": ["Se'ns", "Ens s'", "Nos s'"], "e": "Se va sempre en primer lloc: se + ens → se'ns."},
      {"q": "«No ___ va acudir preguntar-ho.» (a mi)", "o": ["se'm", "em se", "me s'"], "e": "Se + me davant de consonant: se'm va acudir."},
      {"q": "«Demà ___ anirem a primera hora.» (registre formal)", "o": ["ens n'", "se n'", "nos n'"], "e": "Ens n'anirem. La forma se n'anirem és col·loquial i no és adequada en registres formals."},
      {"q": "«No ___ aneu encara, que falten les postres!» (registre formal)", "o": ["vos n'", "se n'", "vos'n"], "e": "Vos + en davant de vocal: vos n'aneu (o us n'aneu). Se n'aneu és col·loquial."},
      {"q": "«Emporteu-vos els documents.» Quina pronominalització és correcta en registre formal?", "o": ["Emporteu-vos-els.", "Emporteu-se'ls.", "Emporteu-vos'ls."], "e": "Vos + els darrere de verb: -vos-els (el segon pronom en forma reforçada)."},
      {"q": "«Vaig explicar als alumnes que l'examen s'ajornava.» Quina pronominalització és correcta?", "o": ["Els ho vaig explicar.", "Els hi vaig explicar.", "Los ho vaig explicar."], "e": "Datiu plural (els) + neutre (ho, l'oració): els ho. Els hi correspondria a datiu + locatiu."},
      {"q": "«Recorda als alumnes que demà hi ha examen.» Quina pronominalització és correcta?", "o": ["Recorda'ls-ho.", "Recorda-los-ho.", "Recorda'ls-hi."], "e": "Darrere de verb acabat en vocal, los pren la forma reduïda: recorda'ls-ho."},
      {"q": "«Vam tornar els llibres als alumnes.» Amb els pronoms posposats:", "o": ["Vam tornar-los-els.", "Vam tornar-los'ls.", "Vam tornar-se'ls."], "e": "Quan el primer pronom acaba en -s, el segon pren la forma reforçada: -los-els."},
      {"q": "«No vull dir res d'això als veïns.» Quina pronominalització és correcta?", "o": ["No els en vull dir res.", "No els n'vull dir res.", "No se'n vull dir res."], "e": "Els (datiu) + en (d'això): darrere de -s, forma reforçada en → els en."},
      {"q": "«De les nostres preocupacions, ___ farem partícip.» (a ell)", "o": ["l'en", "el'n", "le'n"], "e": "Lo + ne davant de consonant: l'en. El pronom pren la forma elidida per a evitar la grafia le, que no existix."},
      {"q": "«Ha tret el cotxe del garatge.» Quina pronominalització és correcta?", "o": ["El n'ha tret.", "L'en ha tret.", "Se n'ha tret."], "e": "Lo + ne davant de vocal: el n'ha tret (l'apòstrof tan a la dreta com siga possible)."},
      {"q": "«___ van regalar la bicicleta per Nadal.» (a mi)", "o": ["Me la", "Em la", "M'la"], "e": "Em, et i es prenen la forma plena quan van en primer lloc d'una combinació anteposada: me la."},
      {"q": "«Quan ___ aniràs a Xàtiva?»", "o": ["te n'", "et n'", "te'n"], "e": "Te + en davant de vocal: te n'aniràs."},
      {"q": "«Posa'm una miqueta de te.» → «Posa___ una miqueta.»", "o": ["-me'n", "'m-en", "-me-ne"], "e": "Me + en posposats: posa-me'n."},
      {"q": "En alguns parlars es diu «els [e] la portaré demà». Com s'ha d'escriure?", "o": ["Els la portaré demà.", "Els e la portaré demà.", "Else la portaré demà."], "e": "La e de suport és acceptable en l'oral dels parlars que la tenen, però no té reflex en l'escriptura."},
      {"q": "Quina duplicació pronominal és correcta per a marcar el contrast?", "o": ["Li ho vaig dir a ell, no a la seua germana.", "Ho vaig dir a ell, no a la seua germana.", "A ell ho vaig dir, no a la seua germana."], "e": "El pronom fort amb funció de complement indirecte (a ell) va duplicat per un pronom feble (li). La duplicació aporta un valor contrastiu."},
      {"q": "Quina construcció amb el pronom fort «a mi» és correcta?", "o": ["M'han avisat a mi.", "Han avisat a mi.", "Han avisat mi."], "e": "Un pronom fort complement directe o indirecte ha d'anar precedit de a i duplicat per un pronom feble: m'han avisat a mi."},
      {"q": "Quina frase evita el pronom «en» redundant?", "o": ["Hi ha poc pa.", "N'hi ha poc de pa.", "N'hi ha poc pa."], "e": "Si el nom ja apareix en la frase, sense dislocar, el pronom en és redundant: hi ha poc pa."},
      {"q": "Quina dislocació és correcta?", "o": ["De pa, n'hi ha poc.", "De pa, hi ha poc.", "Pa, n'hi ha poc de."], "e": "Si el nom es disloca, cal el pronom de represa en i la preposició de: de pa, n'hi ha poc."},
      {"q": "«Ja ___ tinc prou, de vi.»", "o": ["en", "hi", "l'"], "e": "El nom dislocat a la dreta (de vi) es reprén amb en."},
      {"q": "Quina frase evita el pronom datiu redundant?", "o": ["Hem regalat una bicicleta nova al xiquet.", "Li hem regalat una bicicleta nova al xiquet.", "Se li hem regalat una bicicleta nova al xiquet."], "e": "El li pleonàstic amb el complement indirecte posposat és una innovació de la llengua parlada que s'evita en registres formals."},
      {"q": "Quina pregunta és adequada en registre formal?", "o": ["A qui has de dir que t'ajude?", "A qui li has de dir que t'ajude?", "A qui se li has de dir que t'ajude?"], "e": "Amb un interrogatiu o un relatiu de complement indirecte (a qui), el li redundant s'evita en registres formals."},
      {"q": "«Al teu germà, no ___ digues que he vingut.»", "o": ["li", "el", "ho"], "e": "El complement indirecte dislocat a l'esquerra es reprén amb el pronom datiu li. Esta duplicació és correcta."},
      {"q": "«—Has vist la meua germana? —No, encara no l'he ___.» (amb concordança)", "o": ["vista", "vist", "vistes"], "e": "El participi concorda en gènere i nombre amb el pronom acusatiu de tercera persona: l' (la germana) → vista."},
      {"q": "«Les taronges, no me les he ___ jo.» (amb concordança)", "o": ["menjades", "menjat", "menjada"], "e": "Les (taronges) és acusatiu femení plural: menjades."},
      {"q": "«Les veïnes? No ___ he sentides entrar.»", "o": ["les", "els", "li"], "e": "La concordança es manté encara que el temps compost vaja seguit d'un infinitiu: les he sentides entrar."},
      {"q": "«Les sabates que m'agradaven, no me les he ___ comprar.» (amb concordança)", "o": ["pogudes", "pogut", "poguda"], "e": "El pronom anteposat al conjunt verbal fa concordar el participi: me les he pogudes comprar."},
      {"q": "«A Maria, li he escrit una carta.» Per què el participi no concorda en femení?", "o": ["Perquè li és datiu, i la concordança es fa amb els acusatius de tercera persona.", "Perquè Maria és un nom propi.", "Perquè escriure no admet mai la concordança."], "e": "El participi concorda amb lo, la, los, les (acusatius), no amb el datiu li."},
      {"q": "«La veritat, li l'he ___.» (dir, amb concordança)", "o": ["dita", "dit", "dites"], "e": "Concorda amb l' (la veritat, acusatiu), no amb li: li l'he dita."},
      {"q": "Escriu els pronoms: «Explicaré a les alumnes que l'examen s'ajorna.» → «___ explicaré.»", "a": ["els ho"], "e": "Datiu plural + neutre: els ho explicaré."},
      {"q": "Escriu en registre formal: «Li s'ha oblidat la cartera.» → «___ ha oblidat la cartera.»", "a": ["se li"], "e": "Orde formal: se li ha oblidat."},
      {"q": "Escriu el participi concordat: «Les factures, ja les he ___ (pagar).»", "a": ["pagades"], "e": "Les (femení plural) → pagades."},
      {"q": "Escriu el participi concordat: «La porta, l'he ___ (obrir) jo.»", "a": ["oberta"], "e": "L' = la porta → oberta."},
      {"q": "Escriu els pronoms anteposats: «Ha tornat les claus al conserge.» → «___ ha tornades.»", "a": ["li les"], "e": "Li + les: li les ha tornades."},
      {"q": "Escriu en registre formal: «Se n'anirem a les deu.» → «___ anirem a les deu.»", "a": ["ens n'"], "e": "Ens n'anirem; se n'anirem és col·loquial."},
      {"q": "Corregix la frase: «N'hi ha poc de pa.»", "a": ["hi ha poc pa", "hi ha poc pa.", "hi ha poc de pa", "hi ha poc de pa.", "de pa, n'hi ha poc", "de pa, n'hi ha poc."], "e": "Sense dislocació, en és redundant: hi ha poc pa (o, dislocant: de pa, n'hi ha poc)."},
      {"q": "Escriu el pronom feble que duplica el pronom fort: «No ___ han dit res a ella.»", "a": ["li"], "e": "A ella (complement indirecte) es duplica amb li."},
      {"q": "Escriu els pronoms posposats: «Porta l'informe a la directora.» → «Porta-___.»", "a": ["li'l", "l'hi"], "e": "Li + el posposats: porta-li'l (en els parlars septentrionals, porta-l'hi)."}
    ]
  },
  {
    "id": "e5a5e260-b5c8-50a4-8150-af26de2006e9", "type": "c1_mor_relatius", "sort_order": 6,
    "title": "Relatius: usos formals i pleonasmes", "name": "Que, què, qui, on i el qual, relatius neutres, relatiu possessiu, article + que i construccions analítiques",
    "content": "El concepte de relatiu i la seua funció sintàctica, l'ús de l'àton que, el tònic què, el personal qui, l'adverbial (a)on i el variable el qual, els relatius neutres la qual cosa i cosa que, el relatiu possessiu, les estructures article + que i els pleonasmes habituals (3.2.2).", "icon": "🧷", "color": "#D1C4E9",
    "exercises": [
      {"q": "Quina frase conté un pronom feble redundant?", "o": ["El poble on hi vaig nàixer és xicotet.", "El poble on hi ha el castell és xicotet.", "El poble on vaig nàixer és xicotet."], "e": "On ja fa de complement de lloc i hi el repetix. En on hi ha, en canvi, hi forma part del verb haver-hi."},
      {"q": "«És un poble ___ hi ha molta gent.» (registre formal)", "o": ["on", "que", "que allí"], "e": "La construcció sintètica (formal) és on hi ha; que hi ha, amb que com a simple nexe, és analítica i no formal."},
      {"q": "Quina frase és adequada en registre formal?", "o": ["És un tema que no domine.", "És un tema que no el domine.", "És un tema el qual no domine."], "e": "Que ja és el complement directe: el pronom el és redundant. I el qual sense preposició no introduïx especificatives."},
      {"q": "«És un home ___ no lluïx la faena.» (registre formal)", "o": ["a qui", "que li", "a qui li"], "e": "Construcció sintètica: a qui. Que li és analítica i a qui li porta un pronom redundant."},
      {"q": "«És una dona tots els fills ___ són ben educats.»", "o": ["de la qual", "que", "dels quals"], "e": "El relatiu possessiu concorda amb el posseïdor (una dona), no amb el posseït (els fills): de la qual."},
      {"q": "«He anat a uns quants bancs, els caixers ___ no funcionaven.»", "o": ["dels quals", "del qual", "que els seus"], "e": "El posseïdor és plural (uns quants bancs): dels quals. Que els seus és una construcció analítica no formal."},
      {"q": "Quina frase té el relatiu possessiu ben construït?", "o": ["Parla amb Jaume, la paciència del qual és ben notòria.", "Parla amb Jaume, del qual la paciència és ben notòria.", "Parla amb Jaume, que la seua paciència és ben notòria."], "e": "En la construcció possessiva, el nom posseït precedix del qual: la paciència del qual."},
      {"q": "«És una malaltia ___ encara no podem lluitar.»", "o": ["contra la qual", "contra què", "contra que"], "e": "Què i qui només van amb les preposicions àtones a, de, en, amb i per; amb preposicions tòniques s'usa el qual."},
      {"q": "«Els motius ___ ha dimitit són evidents.»", "o": ["per què", "perquè", "pel que"], "e": "Relatiu amb preposició per: per què (o pels quals). Perquè és conjunció i pel que no s'usa amb antecedent."},
      {"q": "«Aquell polític, ___ no té cap escrúpol, ara diu que firmarà.»", "o": ["el qual", "qui", "el que"], "e": "En les explicatives sense preposició, que pot alternar amb el qual, però no amb qui."},
      {"q": "«Va gratificar el client ___ havia tacat.»", "o": ["que", "el qual", "qui"], "e": "En una especificativa sense preposició només és possible que; el qual no hi pot aparéixer."},
      {"q": "«Vam arribar a una ciutat ___ no tenia cotxe ningú.»", "o": ["en què", "en la que", "que"], "e": "Amb antecedent no s'usa article + que: en què, en la qual o on."},
      {"q": "«Este és el lloc ___ ha de començar la carrera.»", "o": ["des d'on", "des de que", "d'on que"], "e": "On pot anar precedit d'altres preposicions locatives: des d'on, cap a on, fins on."},
      {"q": "«Hi ha llengües ___ el subjecte es posa al final de l'oració.» (forma preferible)", "o": ["en què", "a on", "que"], "e": "Quan la localització és metafòrica, es preferix en què o en el qual a on."},
      {"q": "«Això va passar l'any ___ va faltar el pare.»", "o": ["en què", "quan", "on"], "e": "Quan s'usa sense antecedent; amb antecedent explícit (l'any) s'usa que, en què o en el qual."},
      {"q": "«De la manera ___ t'ha contestat, em pense que ja ho sap.»", "o": ["com", "quan", "on"], "e": "Com amb antecedent només és possible darrere de manera o forma (també que, en què, en la qual)."},
      {"q": "«Ha tornat a arribar tard, ___ ha molestat la directora.»", "o": ["cosa que", "lo que", "el que"], "e": "Per a reprendre tota una oració: cosa que o la qual cosa. Lo que i el que no tenen este valor."},
      {"q": "«A partir d'eixe moment va callar, ___ és molt significativa.»", "o": ["la qual cosa", "lo qual", "el qual"], "e": "La qual cosa reprén l'oració; per això l'adjectiu concorda en femení (significativa). Lo qual és un calc."},
      {"q": "«Ahir férem un gran esforç, ___ ara ens permet anar més relaxats.»", "o": ["cosa que", "lo qual", "el que"], "e": "Relatiu neutre: cosa que (o la qual cosa)."},
      {"q": "«El concert va costar trenta mil euros, ___ haurà d'assumir la Diputació.»", "o": ["quantitat que", "lo que", "la que"], "e": "En les explicatives es pot repetir l'antecedent o un sinònim davant de que: quantitat que."},
      {"q": "«Ha hagut de pagar sis-cents euros, ___ és insignificant per a ell.»", "o": ["la qual suma", "la que suma", "lo qual"], "e": "El qual pot fer de determinant d'un sinònim de l'antecedent: la qual suma."},
      {"q": "En quina frase és correcte l'ús d'article + que?", "o": ["El xic alt i el que porta una caçadora negra són companys meus.", "La ciutat en la que visc és tranquil·la.", "El motiu pel que ha dimitit és secret."], "e": "Article + que només s'usa sense antecedent o quan el nom s'ha elidit perquè ja ha aparegut (el [xic] que porta...)."},
      {"q": "«Anirem en el meu cotxe i en ___ portarà Lluïsa.»", "o": ["el que", "el qual", "què"], "e": "El nom cotxe s'ha elidit per no repetir-lo: en el [cotxe] que portarà Lluïsa."},
      {"q": "«Fes ___ consideres més convenient.»", "o": ["el que", "lo que", "què"], "e": "Relativa sense antecedent amb valor neutre: el que (o allò que). Lo que no és correcte."},
      {"q": "«___ ho sàpia, que ho diga.» (forma més formal amb article)", "o": ["El qui", "El qual", "Lo que"], "e": "Sense antecedent i amb determinant, el qui és la forma més formal i tradicional (també el que)."},
      {"q": "«___ t'ho haja dit, t'ha amagat una part de la veritat.»", "o": ["Qui", "Que", "El qual"], "e": "Sense antecedent ni determinant, per a persones s'usa qui."},
      {"q": "«Aquells ___ decidisquen vindre amb mi no se'n penediran.»", "o": ["qui", "quals", "què"], "e": "Darrere del demostratiu, sense antecedent: aquells qui (o aquells que). Quals necessita article i antecedent."},
      {"q": "«L'assumpte ___ et referixes no és competència nostra.»", "o": ["al qual", "al que", "que"], "e": "Referir-se a: cal la preposició davant del relatiu (al qual o a què). Al que no s'usa amb antecedent."},
      {"q": "«La persona en ___ més confie és ma germana.»", "o": ["qui", "que", "la que"], "e": "Persona darrere de preposició àtona: en qui (o en la qual)."},
      {"q": "Quina frase expressa la possessió de manera formal?", "o": ["L'empresa, la directora de la qual és de Morella, ha obert una seu.", "L'empresa, que la seua directora és de Morella, ha obert una seu.", "L'empresa, la qual directora és de Morella, ha obert una seu."], "e": "Possessiu relatiu: nom posseït + del qual / de la qual."},
      {"q": "Quin relatiu NO pot introduir una relativa especificativa sense preposició?", "o": ["el qual", "que", "on"], "e": "El qual sense preposició només apareix en explicatives."},
      {"q": "«La carretera ___ passem normalment l'han tallada per obres.»", "o": ["per la qual", "per la que", "que"], "e": "Amb antecedent i preposició: per la qual (o per on), mai per la que."},
      {"q": "«El joc ___ m'havies parlat me'l vaig comprar ahir.»", "o": ["del qual", "del que", "que"], "e": "Parlar de: del qual (o de què). Del que no és adequat amb antecedent explícit."},
      {"q": "«Aquell home, ___ tots admiraven tant, és un farsant.»", "o": ["a qui", "qui", "a qui li"], "e": "Qui en relatives adjectives va precedit de preposició; a qui li porta un pronom redundant."},
      {"q": "En «Recorde perfectament la motxilla que duia», quina funció fa «que» dins de la relativa?", "o": ["complement directe de duia", "subjecte de duia", "complement del nom motxilla"], "e": "Que representa la motxilla, i la relativa equival a «duia la motxilla»: és el complement directe."},
      {"q": "Escriu el relatiu d'una paraula: «És una persona en ___ confie plenament.»", "a": ["qui"], "e": "Persona darrere de preposició: en qui."},
      {"q": "Completa el relatiu possessiu: «És un jugador l'habilitat ___ és dubtosa.» (dues paraules)", "a": ["del qual"], "e": "L'habilitat del qual: el qual concorda amb el jugador."},
      {"q": "Completa: «No va admetre el torn de rèplica, la qual ___ va ser molt criticada.»", "a": ["cosa"], "e": "La qual cosa reprén tota l'oració anterior."},
      {"q": "Corregix (registre formal): «És un home que no li lluïx la faena.»", "a": ["és un home a qui no lluïx la faena", "és un home a qui no lluïx la faena.", "és un home al qual no lluïx la faena", "és un home al qual no lluïx la faena."], "e": "Construcció sintètica: a qui (o al qual), sense li."},
      {"q": "Corregix (registre formal): «Tinc un amic que el seu pare és obrer.»", "a": ["tinc un amic el pare del qual és obrer", "tinc un amic el pare del qual és obrer."], "e": "Relatiu possessiu: el pare del qual."},
      {"q": "Escriu l'article del relatiu: «És una malaltia contra ___ qual no hi ha vacuna.»", "a": ["la"], "e": "Preposició tònica + el qual concordat: contra la qual."},
      {"q": "Corregix: «Vam arribar a una ciutat en la que no hi havia cotxes.»", "a": ["vam arribar a una ciutat en què no hi havia cotxes", "vam arribar a una ciutat en la qual no hi havia cotxes", "vam arribar a una ciutat on no hi havia cotxes", "vam arribar a una ciutat en què no hi havia cotxes.", "vam arribar a una ciutat en la qual no hi havia cotxes.", "vam arribar a una ciutat on no hi havia cotxes."], "e": "Amb antecedent: en què, en la qual o on, no en la que."},
      {"q": "Escriu el relatiu d'una paraula: «Toca'm el dia ___ tingues alguna molèstia.»", "a": ["que"], "e": "Amb antecedent temporal s'usa que (no quan)."},
      {"q": "Escriu el relatiu d'una paraula: «Vull saber la manera ___ ho has fet.»", "a": ["com", "que"], "e": "Darrere de manera: com (o que)."},
      {"q": "Escriu el relatiu d'una paraula: «El camí per ___ has tornat és més llarg.»", "a": ["on"], "e": "Preposició locativa + on: per on."}
    ]
  },
  {
    "id": "b718c526-1f4f-58ed-8ce4-1a9649b4c7aa", "type": "c1_mor_exclamatius", "sort_order": 7,
    "title": "Exclamatius: quin, quant, que i com", "name": "Funcions de quin, quant, que i com, la construcció quin + substantiu + més + adjectiu i les exclamatives amb que",
    "content": "La precisió en l'ús dels exclamatius, les funcions de quin, quant, que i com, la construcció quin + substantiu + més + adjectiu i les oracions exclamatives completades per que (Que valent que és!) (3.2.2).", "icon": "❗", "color": "#FFCDD2",
    "exercises": [
      {"q": "«___ calor que fa hui!»", "o": ["Quina", "Que", "Què"], "e": "Davant de substantiu s'usa quin/quina; que exclamatiu només modifica adjectius i adverbis."},
      {"q": "Quina exclamativa amb el substantiu «fred» és correcta?", "o": ["Quin fred que fa!", "Que fred que fa!", "Lo fred que fa!"], "e": "Fred és substantiu: quin fred! Que fred és un ús incorrecte de que davant de nom."},
      {"q": "Quina exclamativa NO és correcta?", "o": ["Que fam que tinc!", "Quina fam que tinc!", "Quanta fam que tinc!"], "e": "Fam és substantiu: no admet que exclamatiu. Quina (qualitat) i quanta (quantitat) són correctes."},
      {"q": "En la construcció «quin + substantiu + ___ + adjectiu», quina paraula falta? (Quina xica ___ simpàtica!)", "o": ["més", "molt", "lo"], "e": "La propietat de grau alt s'explicita amb un adjectiu precedit de més: quina xica més simpàtica!"},
      {"q": "«___ gent ha acudit a la presentació!»", "o": ["Quanta", "Quina de", "Que"], "e": "Quant pondera la quantitat i concorda amb el nom: quanta gent."},
      {"q": "«___ de sucre t'has posat al café!»", "o": ["Quant", "Quanta", "Que"], "e": "Davant d'un nom masculí singular, quant va seguit de de: quant de sucre."},
      {"q": "«___ temps sense vore't!»", "o": ["Quant de", "Quanta", "Que"], "e": "Nom masculí singular: quant de temps."},
      {"q": "«___ ganes de vore't que tenia!»", "o": ["Quantes", "Quants", "Que"], "e": "Ganes és femení plural: quantes ganes."},
      {"q": "«___ coses que no podrem aprofitar!»", "o": ["Quantes", "Quants", "Que"], "e": "Quant concorda amb el nom: quantes coses."},
      {"q": "«___ que saps, xiquet!» (pondera el verb)", "o": ["Quant", "Quanta", "Quin"], "e": "Amb valor adverbial, quant queda invariable i pondera l'acció: quant que saps!"},
      {"q": "«___ pesat que és el teu amic!»", "o": ["Que", "Què", "Quin"], "e": "Davant d'adjectiu, l'exclamatiu és que (àton, sense accent)."},
      {"q": "«___ lluny que viu ara!»", "o": ["Que", "Quin", "Quant de"], "e": "Davant d'adverbi: que lluny!"},
      {"q": "Quin orde és correcte en esta exclamativa amb «que»?", "o": ["Que bé que parla ta mare!", "Que bé ta mare parla!", "Que bé que ta mare parla!"], "e": "L'exclamatiu va al principi i el subjecte es posposa al final: que bé que parla ta mare!"},
      {"q": "Quin orde és correcte en esta exclamativa amb «quants»?", "o": ["Quants llibres que té Lluís!", "Quants llibres Lluís té!", "Quants llibres que Lluís té!"], "e": "Quan l'exclamatiu no afecta el subjecte, el subjecte va al final de l'oració."},
      {"q": "«___ la vull!» ('la vull molt')", "o": ["Com", "Que", "Quant de"], "e": "Com davant de verb pondera la quantitat (= molt) o la manera."},
      {"q": "Quina exclamativa amb «com» és correcta?", "o": ["Com està d'alta la xiqueta!", "Com està alta la xiqueta!", "Com està de alta la xiqueta!"], "e": "Amb com, l'adjectiu o l'adverbi s'introduïx amb de, apostrofada davant de vocal: d'alta."},
      {"q": "«Com és ___ verderol, este xiquet!»", "o": ["de", "tan", "molt"], "e": "Com + verb + de + adjectiu: com és de verderol!"},
      {"q": "«___ s'ha posat per no res!» ('de quina manera')", "o": ["Com", "Quin", "Que"], "e": "Com també pondera la manera: com s'ha posat!"},
      {"q": "«___ ho diria!»", "o": ["Qui", "Què", "Que"], "e": "Qui també té valor exclamatiu en expressions com qui ho diria!"},
      {"q": "Quina exclamativa està ben escrita?", "o": ["Que sabuda que és!", "Que sabuda què és!", "Què sabuda que és!"], "e": "Tant l'exclamatiu que com la conjunció que posterior són àtons i no porten accent."},
      {"q": "«Que valent que és!» Què és el segon «que»?", "o": ["una conjunció àtona que enllaça el sintagma exclamatiu amb la resta, i que es pot ometre", "un pronom interrogatiu tònic", "un error que cal suprimir"], "e": "Després del sintagma exclamatiu apareix normalment un que àton, d'ús potestatiu: que valent (que) és!"},
      {"q": "«Amb lo bonic que és, i no para de plorar!» Quina és l'alternativa correcta?", "o": ["Tan bonic que és, i no para de plorar!", "Lo bonic que és, i no para de plorar!", "El bonic que és, i no para de plorar!"], "e": "L'article neutre no és acceptable amb valor intensiu: tan bonic que (o com) és."},
      {"q": "«No saps lo bé que treballen.» Quina és l'alternativa correcta?", "o": ["No saps com treballen de bé.", "No saps el bé que treballen.", "No saps lo bé que treballen."], "e": "En lloc de lo intensiu: com + verb + de + adverbi: com treballen de bé."},
      {"q": "Quins exclamatius són variables en gènere i nombre?", "o": ["quin i quant", "que i com", "qui i com"], "e": "Quin i quant varien (quina, quants...); que, com i qui són invariables."},
      {"q": "Quin exclamatiu només pot quantificar un adjectiu o un adverbi?", "o": ["que", "quin", "quant"], "e": "Que modifica adjectius i adverbis; quin i quant, substantius."},
      {"q": "Quina diferència hi ha entre «Quina gent!» i «Quanta gent!»?", "o": ["Quin és qualitatiu; quant és quantitatiu.", "Quin és quantitatiu; quant és qualitatiu.", "No n'hi ha cap: són sinònims."], "e": "Quin atribuïx una qualitat en grau alt; quant pondera la quantitat."},
      {"q": "«___ barbaritat acabes de dir!»", "o": ["Quina", "Que", "Quanta de"], "e": "Barbaritat és substantiu: quina barbaritat (que) acabes de dir!"},
      {"q": "En «Llàstima que no vinga!», quin exclamatiu s'ha elidit?", "o": ["quina", "que", "com"], "e": "És possible elidir l'exclamatiu: (Quina) llàstima que no vinga!"},
      {"q": "«___ està plovent!» (sorpresa)", "o": ["Si", "Sí", "Què"], "e": "Hi ha exclamatives introduïdes per l'adverbi exclamatiu si, sense accent: si està plovent!"},
      {"q": "«Però ___ dius!» (exclamativa)", "o": ["què", "que", "qué"], "e": "Una interrogativa pot convertir-se en exclamativa per l'entonació; el pronom manté l'accent obert: què dius!"},
      {"q": "«___ vergonya més gran!»", "o": ["Quina", "Que", "Quanta de"], "e": "Quin + substantiu + més + adjectiu: quina vergonya més gran!"},
      {"q": "«Com s'ha quedat de lluny, el teu amic!» Quina funció fa «com»?", "o": ["modificador del verb, que indica un grau alt", "modificador d'un substantiu", "pronom relatiu"], "e": "Com és un exclamatiu adverbial que modifica el predicat; l'adverbi s'introduïx amb de."},
      {"q": "Completa amb l'exclamatiu: «___ fred que fa!»", "a": ["quin"], "e": "Fred és substantiu: quin fred!"},
      {"q": "Completa amb l'exclamatiu: «___ bé que parla!»", "a": ["que"], "e": "Davant d'adverbi: que bé!"},
      {"q": "Completa: «Quina pel·lícula ___ bonica!»", "a": ["més"], "e": "Quin + substantiu + més + adjectiu."},
      {"q": "Completa amb l'exclamatiu: «___ de soroll que fan els veïns!»", "a": ["quant"], "e": "Nom masculí singular: quant de soroll."},
      {"q": "Completa amb l'exclamatiu: «___ està d'alta la xiqueta!»", "a": ["com"], "e": "Com + verb + de + adjectiu."},
      {"q": "Completa amb una preposició: «No saps com treballen ___ bé.»", "a": ["de"], "e": "Com treballen de bé (no lo bé que treballen)."},
      {"q": "Completa amb l'exclamatiu: «___ gent que hi havia a la plaça!»", "a": ["quanta"], "e": "Gent, femení singular: quanta gent."},
      {"q": "Completa amb la conjunció: «Que valent ___ és!»", "a": ["que"], "e": "El que àton enllaça el sintagma exclamatiu amb la resta."},
      {"q": "Corregix l'exclamativa: «Que calor més apegalosa!»", "a": ["quina calor més apegalosa!", "quina calor més apegalosa"], "e": "Calor és substantiu: quina calor més apegalosa!"},
      {"q": "Completa amb l'exclamatiu: «___ ho hauria dit!»", "a": ["qui"], "e": "Qui exclamatiu: qui ho hauria dit!"}
    ]
  },
  {
    "id": "b76fad99-284c-5367-981a-3ec938e46cf1", "type": "c1_mor_quantificadors", "sort_order": 8,
    "title": "Quantificadors: numerals, indefinits i quantitatius", "name": "U/un, xifres romanes, multiplicatius, col·lectius, indefinits, quantitatius invariables i locucions de quantitat",
    "content": "La concordança dels cardinals (u/un) i la seua escriptura amb xifra o amb lletra, la lectura de les xifres romanes posposades, els multiplicatius variables i invariables i les perífrasis equivalents, els col·lectius (parell, dotzena, centenar, miler), els indefinits qualsevol, hom, cada u/cadascú i la resta, els quantitatius invariables (gens, massa, menys/manco, més, prou), les locucions quantitatives (com més, com a màxim, a tot estirar, pel cap alt, si més no, pel cap baix) i les construccions res de + adjectiu i res a + infinitiu (3.2.2).", "icon": "🔢", "color": "#FFE0B2",
    "exercises": [
      {"q": "«No he pogut passar de la pàgina ___.»", "o": ["u", "un", "una"], "e": "Quan el cardinal funciona com a ordinal (pàgina u, capítol u) s'usa la forma u."},
      {"q": "«Dona-me'n ___ d'aquells, de melons.»", "o": ["un", "u", "uno"], "e": "Quan el numeral modifica un substantiu, explícit o implícit (pronominalitzat per en), s'usa un."},
      {"q": "«—Ja han marcat algun gol? —Sí, van dos a ___.»", "o": ["u", "un", "una"], "e": "Quan el numeral no modifica cap substantiu (el resultat, el nom del número) s'usa u."},
      {"q": "«Llegiu el capítol ___.» (21)", "o": ["vint-i-u", "vint-i-un", "vint-i-uné"], "e": "Posposat a un substantiu on es pressuposa «número», el cardinal fa d'ordinal i adopta la forma u: el capítol vint-i-u."},
      {"q": "«Obriu el llibre per la pàgina ___.» (300)", "o": ["tres-cents", "tres-centes", "tres-centena"], "e": "Usats com a ordinals, els cardinals que varien adopten només la forma masculina: la pàgina tres-cents."},
      {"q": "«El pressupost és de tres ___ d'euros.»", "o": ["milions", "milió", "milions de milió"], "e": "Milió, bilió, etc. són substantius i fan plural: tres milions d'euros."},
      {"q": "Segons la tradició tipogràfica que recull la GNV, quina frase escriu els números de la manera habitual?", "o": ["Només caben nou taules en l'aula 205.", "Només caben 9 taules en l'aula dos-cents cinc.", "Només caben 9 taules en l'aula 205."], "e": "Dins del text, els cardinals se solen escriure amb lletra del zero al nou i amb xifres a partir del 10."},
      {"q": "Com es llig «Joan XXIII»?", "o": ["Joan vint-i-tres", "Joan vint-i-tresé", "Joan vigèsim tercer"], "e": "Les xifres romanes posposades a un nom propi i superiors a deu es lligen com a cardinals."},
      {"q": "Com es llig «Jaume II»?", "o": ["Jaume segon", "Jaume dos", "Jaume dosé"], "e": "Fins a deu, les xifres romanes es lligen com a ordinals: Jaume segon, Joan Pau segon."},
      {"q": "Com es llig «Carles V»?", "o": ["Carles cinqué", "Carles cinc", "Carles quinzé"], "e": "Inferior a deu: es llig com a ordinal (cinqué, o la forma culta quint)."},
      {"q": "Com es lligen les «III Jornades de Sociolingüística»?", "o": ["terceres", "tres", "tercera"], "e": "Anteposades, les xifres romanes es lligen com a ordinals i concorden: les terceres jornades."},
      {"q": "Quin multiplicatiu equival a «quatre voltes més»?", "o": ["quàdruple", "quíntuple", "quadrúpede"], "e": "Doble (2), triple (3), quàdruple (4), quíntuple (5), sèxtuple (6). Quadrúpede és un animal de quatre potes."},
      {"q": "Quin multiplicatiu no admet mai variació de gènere?", "o": ["doble", "triple", "quíntuple"], "e": "Amb l'excepció de doble, els multiplicatius poden variar quan valen 'tantes voltes una xifra' (quíntupla)."},
      {"q": "«Va ser signada ___ aliança entre els tres regnes.»", "o": ["la triple", "la tripla", "la triplada"], "e": "Quan designen el nombre d'elements que componen una entitat, els multiplicatius són invariables: la triple aliança."},
      {"q": "«És una quantitat ___ que l'altra.» (cinc voltes més)", "o": ["quíntuple (o quíntupla)", "quintuplicada a", "cinquena"], "e": "Amb el valor 'tantes voltes una xifra' s'admet la variació: quíntuple o quíntupla."},
      {"q": "Quina perífrasi equival a «sèxtuple»?", "o": ["sis vegades més", "sis vegades menys", "la sisena part"], "e": "En la llengua parlada, a partir de quàdruple, es preferix tantes vegades (o voltes) més: sis vegades més car."},
      {"q": "«Han detingut ___ de manifestants.» (1.000 aprox.)", "o": ["un miler", "un mil·lenari", "un milió"], "e": "Miler (o milenar) és el col·lectiu de 1.000; mil·lenari és l'efemèride."},
      {"q": "Com s'anomena un període de dos anys?", "o": ["bienni", "bimestre", "bisíl·lab"], "e": "Bienni (2 anys), bimestre (2 mesos), bisíl·lab (2 síl·labes)."},
      {"q": "«La mesura combat ___ pràctiques abusives.»", "o": ["qualssevol", "qualsevols", "qualsevol de"], "e": "En plural: qualssevol (duplicació gràfica de la s, sense diferència en la pronúncia)."},
      {"q": "«Deixa'm tres bolígrafs ___.»", "o": ["qualssevol", "qualsevol", "qualsevols"], "e": "Posposat al nom, qualsevol concorda en nombre: tres bolígrafs qualssevol."},
      {"q": "Quina alternativa és la més habitual hui per a la frase formal «Hom pensava que la Terra era plana»?", "o": ["Es pensava que la Terra era plana.", "Un pensaven que la Terra era plana.", "Tothom pensaven que la Terra era plana."], "e": "Hom se sent arcaic i molt formal; s'usen construccions impersonals com la passiva pronominal: es pensava."},
      {"q": "«Parlaren els tres candidats i ___ digué la seua opinió.»", "o": ["cadascun", "cadascú", "cada"], "e": "Amb antecedent discursiu (els candidats) s'usa el quantificador cadascun (o cada un), que admet «d'ells»."},
      {"q": "«___ ha de ser responsable dels seus actes.» (valor genèric, sense antecedent)", "o": ["Cadascú", "Cadascun", "Cada"], "e": "El pronom genèric, sense antecedent, és cadascú (o cada u), sense -n."},
      {"q": "«Els dos amics portaven ___ carpetes.» (una cadascun, registre molt formal)", "o": ["sengles", "ambdós", "senglars"], "e": "Sengles: 'un per a cadascuna de les persones o coses esmentades'. És molt formal; hui s'usa «una carpeta cadascun»."},
      {"q": "«Ja t'he pagat la mitat; ___ te la pagaré el mes que ve.»", "o": ["la resta", "lo demés", "lo restant"], "e": "La resta: la part que queda. Les formes amb l'article neutre lo s'eviten en els registres formals."},
      {"q": "Quin quantitatiu porta SEMPRE la preposició de davant del nom?", "o": ["gens", "massa", "prou"], "e": "Gens de pa, gens de diners. Massa no en porta mai; prou, només davant de masculí singular."},
      {"q": "«Ens queda ___ farina per a fer la coca.»", "o": ["prou", "prou de", "proua"], "e": "Prou porta de només davant de masculí singular (prou de pa); davant de femení: prou farina."},
      {"q": "Quina forma és sinònima de «menys» i es conserva en expressions com «més o ___»?", "o": ["manco", "menco", "manc"], "e": "Manco es manté viu en algunes comarques: més o manco, ni menys ni manco, almanco."},
      {"q": "«Ara treballem ___ que abans.» (inferioritat, sense «menys»)", "o": ["més poc", "més menys", "tan poc de"], "e": "Amb valor d'inferioritat també s'usa més poc: ara treballem més poc que abans."},
      {"q": "«___ estudies, més aprendràs.»", "o": ["Com més", "Mentre més", "Contra més"], "e": "La comparació proporcional s'expressa amb com més... més. «Mentre més» i «contra més» són calcs del castellà."},
      {"q": "«Vine ___ prompte millor.»", "o": ["com més", "lo més", "contra més"], "e": "Alternativa a «lo més prompte possible»: com més prompte millor (o al més prompte possible)."},
      {"q": "«Hi havia, ___, dues-centes persones; segurament més.» (com a mínim)", "o": ["pel cap baix", "pel cap alt", "a tot estirar"], "e": "Pel cap baix i si més no = com a mínim. Pel cap alt i a tot estirar = com a màxim."},
      {"q": "«Acabarem demà o, ___, despús-demà.» (com a màxim)", "o": ["a tot estirar", "pel cap baix", "si més no"], "e": "A tot estirar, pel cap alt, com a molt = com a màxim."},
      {"q": "«Caldria fer-ho, ___, per a fer callar les crítiques.» (almenys)", "o": ["si més no", "pel cap alt", "com a molt"], "e": "Si més no és sinònim d'almenys i com a mínim."},
      {"q": "«La reunió no ha portat res ___ transcendent.»", "o": ["de", "que", "a"], "e": "El pronom res pren la preposició de davant d'adjectius: res de transcendent, res d'important, res de bo."},
      {"q": "«Amb un rival tan superior, no tenen ___.»", "o": ["res a fer", "gens a fer", "cap a fer"], "e": "La construcció fraseològica és res a + infinitiu: no tenen res a fer."},
      {"q": "En registre formal, quina frase és l'adequada?", "o": ["No tinc cap diccionari de rus.", "No tinc cap de diccionari de rus.", "No tinc gens de diccionaris de rus."], "e": "L'ús de cap de + nom és propi d'alguns parlars i no és habitual en els registres formals. Gens no va amb comptables."},
      {"q": "Escriu el numeral en lletres: «L'___ de maig és festa.» (1)", "a": ["u"], "e": "L'u de maig: el primer dia del mes es diu amb u."},
      {"q": "Escriu en lletres com es llig «Lluís XIV».", "a": ["catorze", "lluís catorze"], "e": "Superior a deu i posposat a nom propi: cardinal."},
      {"q": "Escriu el plural de «qualsevol» en «Accepten ___ altres ajudes».", "a": ["qualssevol"], "e": "Qualssevol."},
      {"q": "Escriu el col·lectiu de 2: «Un ___ de pantalons».", "a": ["parell"], "e": "Parell (2), dotzena (12), centenar (100), miler (1.000)."},
      {"q": "Completa la locució de valor 'com a màxim': «Disposeu, pel cap ___, de tres hores.»", "a": ["alt"], "e": "Pel cap alt = com a màxim; pel cap baix = com a mínim."},
      {"q": "Completa amb la forma femenina adequada: «Han vingut tres-___ persones.»", "a": ["centes"], "e": "Tres-centes persones: cent fa el femení plural centes."},
      {"q": "Completa l'expressió amb el pronom genèric de persona: «___ sempre ha de ser conseqüent amb les seues idees.» (forma d'una lletra)", "a": ["u", "un"], "e": "El pronom indefinit u (també un) té valor genèric: U sempre ha de ser conseqüent."},
      {"q": "Completa amb un quantitatiu (comparació proporcional): «Com ___ ho penses, menys ho entens.»", "a": ["més"], "e": "Com més... menys / com més... més."}
    ]
  },
  {
    "id": "9a4def44-bf7a-574c-9844-284a6e7ad538", "type": "c1_mor_preposicions", "sort_order": 9,
    "title": "Preposicions: compostes, al/en + infinitiu i caiguda", "name": "Àtones i tòniques, locucions, cap a, fins a, com a, per a, al/en + infinitiu, usos de a, de, en i amb, i elisió i canvi de preposicions",
    "content": "La precisió en l'ús de les preposicions àtones i tòniques i de les locucions prepositives, les preposicions compostes (cap a, fins a, com a, per a), la construcció temporal en o al + infinitiu, usos diversos de a, de, en i amb, i l'elisió i el canvi de les preposicions àtones (3.2.2).", "icon": "🔗", "color": "#D1C4E9",
    "exercises": [
      {"q": "Quina d'estes preposicions és tònica?", "o": ["sense", "amb", "per"], "e": "Són àtones a, en, de, amb i per (i les compostes); les altres preposicions simples, com sense, entre o contra, són tòniques."},
      {"q": "Quina d'estes NO és una preposició composta?", "o": ["sense", "cap a", "com a"], "e": "Les compostes són des de, fins a, cap a, per a i com a."},
      {"q": "«Ahir vam sopar ___ els meus pares.»", "o": ["amb", "en", "a"], "e": "En registre formal cal distingir amb (companyia) de en: sopar amb algú."},
      {"q": "«Se n'han anat ___ allí.»", "o": ["cap", "cap a", "cap an"], "e": "Cap a es reduïx a cap davant dels adverbis ací, allí, allà, amunt, avall... i dels demostratius aquest, aqueix, aquell."},
      {"q": "«Anem ___ eixe carrer.»", "o": ["cap a", "cap", "cap en"], "e": "Davant d'eixe es manté cap a (la reducció es fa davant d'aquest, aqueix, aquell)."},
      {"q": "«No començarem l'obra ___ demà.»", "o": ["fins", "fins a", "fins de"], "e": "Amb adverbis díctics (ahir, demà, ara) s'usa fins: fins demà, fins ara."},
      {"q": "«Espera't, que no el trobaràs ___ les onze de la nit.»", "o": ["fins a", "fins", "fins en"], "e": "Amb una data o hora precisa i amb infinitius s'usa fins a: fins a les onze."},
      {"q": "«___ fa poc no en teníem notícies.»", "o": ["Fins", "Fins a", "Fins de"], "e": "Davant de que i de fa s'usa fins: fins fa poc, fins que vinga."},
      {"q": "«L'experiència es valorarà ___ un màxim de dos punts.»", "o": ["fins a", "fins", "cap a"], "e": "En els usos no espacials ni temporals es manté fins a: fins a un màxim de, fins a sis persones."},
      {"q": "«Actuava ___ president de la comissió.»", "o": ["com a", "com", "de com"], "e": "Com a amb valor predicatiu, 'en qualitat de'."},
      {"q": "«Plorava ___ un xiquet.»", "o": ["com", "com a", "com de"], "e": "Quan el terme porta determinant (un, el...), com a es reduïx a com."},
      {"q": "«Menjaven ___ llops.»", "o": ["com a", "com uns de", "com de"], "e": "Sense determinant, en la comparació es manté com a: com a llops (però com uns llops)."},
      {"q": "«___ passar per la plaça ens va saludar.» (mentre passava)", "o": ["Al", "En", "De"], "e": "Al + infinitiu té valor duratiu: l'acció principal passa dins de l'interval ('mentre passava')."},
      {"q": "«___ arribar el pare, avisa'm.» (just després que arribe)", "o": ["En", "Al", "Per"], "e": "En + infinitiu indica anterioritat immediata: primer arriba el pare i tot seguit m'avises."},
      {"q": "Quina frase és correcta en registre formal?", "o": ["Com que era tan tard, se n'anaren.", "Al ser tan tard, se n'anaren.", "En ser tan tard, se n'anaren."], "e": "Les construccions al/en + infinitiu amb valor exclusivament causal no són adequades: cal una causal com que."},
      {"q": "«Esta caixa ens servirà ___ guardar les revistes.»", "o": ["per a", "per", "a"], "e": "Per a introduïx els complements finals sense intencionalitat (subjecte inanimat)."},
      {"q": "«No menja ___ no embrutar.»", "o": ["per", "per a", "a"], "e": "Per introduïx finals amb matís de causa no efectiva: la intenció de no fer una cosa."},
      {"q": "«Tots aquells pisos estan ___ vendre.»", "o": ["per", "per a", "a"], "e": "Per + infinitiu indica mancança: estan per vendre ('encara no s'han venut')."},
      {"q": "«No tinc prou informació ___ decidir-me.»", "o": ["per a", "per", "de"], "e": "Quan l'infinitiu final modifica un adjectiu, un nom o un quantitatiu s'usa per a."},
      {"q": "«Tinc classe d'informàtica tres vegades ___ setmana.»", "o": ["a la", "en la", "per a la"], "e": "La preposició a expressa la distribució en relació amb una unitat de temps: tres vegades a la setmana."},
      {"q": "«Treballa ___ valent.» (amb molt d'esforç)", "o": ["de", "a", "en"], "e": "De valent: la preposició de introduïx la manera."},
      {"q": "«No en vull, ___ pa.»", "o": ["de", "(sense preposició)", "del"], "e": "En les dislocacions a la dreta la preposició de és obligatòria: no en vull, de pa."},
      {"q": "«Les obres acabaran ___ desembre.» (cap a la meitat del mes)", "o": ["a mitjan", "a mitjans de", "a mitjant"], "e": "A mitjan va seguida d'un substantiu sense determinant: a mitjan desembre."},
      {"q": "«___ arribar a les nou, arribaran a les deu.» (en lloc de)", "o": ["En compte d'", "En compte a", "A compte d'"], "e": "En compte de (o per compte de): substitució."},
      {"q": "«___ estudiar, ha aprovat les oposicions.»", "o": ["A força d'", "A força a", "Per força a"], "e": "A força de (o a còpia de): repetició esforçada d'una acció."},
      {"q": "«___ les pluges, els pantans s'han recuperat.» (a conseqüència de)", "o": ["Arran de", "Arrant de", "A arrel de"], "e": "Arran de, en sentit figurat, equival a a conseqüència de."},
      {"q": "«Va publicar l'informe ___ garantir-ne la difusió.»", "o": ["a fi de", "a fi a", "al fi de"], "e": "A fi de (o per tal de): finalitat."},
      {"q": "«Insistia ___ era innocent.»", "o": ["que", "en que", "a que"], "e": "Insistir en el tema, però insistia que era innocent: la preposició cau davant de la conjunció que."},
      {"q": "«___ m'ho has dit, ho he sabut a temps.»", "o": ["Gràcies que", "Gràcies a que", "Gràcies de que"], "e": "Gràcies a ell, però gràcies que m'ho has dit: la preposició a cau davant de que."},
      {"q": "«L'amenaçà ___ l'expulsaria.»", "o": ["que", "amb que", "de que"], "e": "Amenaçar amb l'expulsió, però l'amenaçà que l'expulsaria."},
      {"q": "«No ha obert la boca ___ ha arribat.»", "o": ["des que", "des de que", "desde que"], "e": "Des d'este matí, però des que ha arribat."},
      {"q": "Quina és l'alternativa recomanada a «L'obligaren que declarara»?", "o": ["L'obligaren a declarar.", "L'obligaren a que declarara.", "L'obligaren de declarar."], "e": "Quan la caiguda força massa la frase, es pot usar una oració d'infinitiu."},
      {"q": "«Encara no m'he acostumat ___ ja no visca amb nosaltres.»", "o": ["al fet que", "a que", "de que"], "e": "Per a evitar una construcció forçada es pot intercalar un nom genèric: al fet que."},
      {"q": "«Tarden molt ___ acabar la faena.»", "o": ["a", "en", "de"], "e": "Tardar en la presa de decisions, però tardar a + infinitiu: canvi de preposició."},
      {"q": "«M'amenaça ___ dir-li-ho tot.»", "o": ["de", "amb", "a"], "e": "Amenaçar amb + nom, però amenaçar de + infinitiu."},
      {"q": "«Sempre és el primer ___ parlar.»", "o": ["a", "en", "de"], "e": "Ser el primer en una cosa, però el primer a + infinitiu."},
      {"q": "Quina és l'alternativa recomanada a la seqüència col·loquial «Ves a per pa»?", "o": ["Ves a comprar pa.", "Ves per a pa.", "Ves a pa."], "e": "Per a evitar la seqüència a + per, millor un verb més precís: ves a comprar pa, ves a buscar el teu germà."},
      {"q": "Escriu la preposició (destinació): «L'avió ix ___ Londres d'ací a vint minuts.»", "a": ["per a"], "e": "Davant de sintagma nominal, per a introduïx la destinació."},
      {"q": "Escriu «com a» o «com»: «T'ho dic ___ amiga.»", "a": ["com a"], "e": "Com a amb valor predicatiu ('en qualitat de'), sense determinant."},
      {"q": "Escriu la preposició (finalitat sense intenció): «Menges massa ___ aprimar-te.»", "a": ["per a"], "e": "Per a amb infinitiu que modifica un quantitatiu."},
      {"q": "Escriu la preposició que cal davant de l'infinitiu: «S'ha afanyat ___ presentar el disc.»", "a": ["a"], "e": "Afanyar-se en + nom, però afanyar-se a + infinitiu."},
      {"q": "Corregix la frase: «Confiava en que guanyaria el premi.»", "a": ["confiava que guanyaria el premi"], "e": "La preposició en cau davant de la conjunció que."},
      {"q": "Escriu la forma reduïda de «cap a» que correspon: «Mira ___ amunt.»", "a": ["cap"], "e": "Cap amunt, cap avall, cap allí: reducció davant d'adverbis direccionals i demostratius."},
      {"q": "Corregix la frase: «Estudia per por de que el suspenguen.»", "a": ["estudia per por que el suspenguen"], "e": "Por de suspendre, però por que el suspenguen."},
      {"q": "Completa la locució (substitució): «Hi anirem en metro, en ___ d'anar-hi en cotxe.»", "a": ["compte", "lloc"], "e": "En compte de (o en lloc de): substitució."}
    ]
  },
  {
    "id": "b324e23b-8a7d-5998-b137-9dd2d94fadf0", "type": "c1_mor_adverbis", "sort_order": 10,
    "title": "Adverbis: dubte, negació, -ment i lloc", "name": "Potser i pot ser que, afirmació i negació, paraules negatives, adverbis en -ment coordinats, baix/davall/sota i només/no més",
    "content": "Els adverbis i locucions modals de dubte i probabilitat (potser + indicatiu, pot ser que + subjuntiu, tal vegada, qui sap), d'afirmació i de negació (sens dubte, de cap manera, en absolut) i l'ús de no amb paraules negatives, la coordinació dels adverbis en -ment, i la precisió en l'ús de baix, davall i sota, de sols, solament i a soles, i la distinció només / no més (3.2.2).", "icon": "🧩", "color": "#B2EBF2",
    "exercises": [
      {"q": "En registre formal, quina frase és la recomanada?", "o": ["Potser vindrà demà.", "Potser vinga demà.", "Pot ser vindrà demà."], "e": "Amb potser, el mode tradicional és l'indicatiu; el subjuntiu és una innovació que convé evitar en els registres formals."},
      {"q": "«Pot ser que ___ demà.»", "o": ["vinga", "vindrà", "ve"], "e": "Pot ser que (verb poder + ser) regix subjuntiu: pot ser que vinga."},
      {"q": "«___ era lleig, però tenia un atractiu especial.»", "o": ["Potser", "Pot ser", "Pot-ser"], "e": "Potser és un adverbi compost i s'escriu en una sola paraula."},
      {"q": "Quina construcció exigix el subjuntiu?", "o": ["pot ser que", "potser", "tal vegada"], "e": "Potser i tal vegada van tradicionalment amb indicatiu; pot ser que és una oració que regix subjuntiu."},
      {"q": "En registre formal, amb quin mode van «possiblement», «potser» o «tal vegada»?", "o": ["indicatiu", "subjuntiu", "imperatiu"], "e": "L'indicatiu és el mode tradicional amb els adverbis de dubte: possiblement arribaran demà."},
      {"q": "Quin adverbi modal NO acaba en -ment?", "o": ["potser", "segurament", "aparentment"], "e": "Els adverbis modals són en -ment, amb l'excepció de potser, paraula composta."},
      {"q": "Quina és l'alternativa a «A lo millor ve en el tren de les deu»?", "o": ["Tal vegada vindrà en el tren de les deu.", "A lo mejor vindrà en el tren de les deu.", "Lo més segur vinga en el tren de les deu."], "e": "En lloc de «a lo millor», s'usa tal vegada o potser, amb indicatiu."},
      {"q": "«Aquells diners venen de ___ on.» (ningú no ho sap)", "o": ["qui sap", "quin sap", "qui sab"], "e": "Qui sap és una locució de dubte, com tal vegada o tal volta."},
      {"q": "Quina d'estes locucions expressa negació?", "o": ["de cap manera", "sens dubte", "de veres"], "e": "De cap manera (o de ninguna manera) i en absolut neguen; sens dubte i de veres afirmen."},
      {"q": "Quina d'estes expressions expressa afirmació?", "o": ["sens dubte", "en absolut", "no gens"], "e": "Sens dubte, efectivament o de veritat afirmen; en absolut i no gens neguen."},
      {"q": "«—Què t'abellix? —___.»", "o": ["Res (o No res).", "Res no (només).", "Nada."], "e": "Les paraules negatives poden respondre soles o precedides de no: Res / No res."},
      {"q": "«—Quan t'agradaria tornar-hi? —___.»", "o": ["Mai (o No mai).", "Mai no.", "Nunca."], "e": "Mai pot respondre sol o amb no davant: Mai / No mai."},
      {"q": "Quina frase és correcta?", "o": ["No l'ha convidat ningú.", "L'ha convidat ningú.", "Ningú l'ha no convidat."], "e": "Les paraules negatives posposades al verb exigixen l'adverbi no."},
      {"q": "Quina afirmació és correcta sobre «Ningú (no) l'ha convidat»?", "o": ["Amb ningú anteposat, el no és opcional.", "El no és obligatori.", "El no és incorrecte."], "e": "Si la paraula negativa va davant del verb, són acceptables les dos opcions, encara que hui es tendix a ometre el no."},
      {"q": "«Has anat ___ a les Columbretes?» (alguna vegada)", "o": ["mai", "nunca", "jamai"], "e": "En les preguntes, mai té valor positiu: 'alguna vegada'."},
      {"q": "Què significa «Si vols res, avisa'm»?", "o": ["Si vols alguna cosa, avisa'm.", "Si no vols cap cosa, avisa'm.", "Si vols tot, avisa'm."], "e": "En les condicionals, res té valor afirmatiu: alguna cosa."},
      {"q": "«—Ho sabies tu? —No. Jo ___ ho sabia.»", "o": ["tampoc (no)", "també no", "tampoc sí"], "e": "Tampoc funciona com les paraules negatives: anteposat al verb, el no és opcional."},
      {"q": "«El van rebre ___ i amablement.» (cordial)", "o": ["cordialment", "cordial", "cordials"], "e": "En la coordinació, l'AVL permet elidir -ment del segon adverbi; en el primer s'ha de mantindre."},
      {"q": "Segons la normativa de l'AVL, en la coordinació d'adverbis en -ment...", "o": ["es pot elidir -ment del segon, però es preferix mantindre'l en tots dos.", "s'ha d'elidir -ment del primer.", "no es pot elidir mai -ment."], "e": "Caminava tranquil·lament i lenta (o, millor, tranquil·lament i lentament)."},
      {"q": "Quina és la coordinació més habitual hui?", "o": ["Va gestionar el departament hàbilment i eficaçment.", "Va gestionar el departament hàbil i eficaçment.", "Va gestionar el departament hàbils i eficaços."], "e": "Tot i que es pot elidir -ment del segon, hui és més habitual mantindre'l en tots dos."},
      {"q": "Quina coordinació admet la GVB amb elisió del sufix?", "o": ["Caminava tranquil·lament i lenta.", "Caminava tranquil·la i lenta.", "Caminava tranquil i lentament."], "e": "L'elisió afecta el segon adverbi (i següents): tranquil·lament i lenta."},
      {"q": "Escriu l'adverbi en -ment derivat de «cortés».", "a": ["cortesament"], "e": "L'adverbi es forma sobre el femení de l'adjectiu: cortesa → cortesament."},
      {"q": "«El gat dorm ___ la taula.»", "o": ["davall de", "baix de", "debaix de"], "e": "Davall indica la part inferior en direcció vertical; baix seguit de complement amb este valor no és acceptable."},
      {"q": "«Ves-te'n ___ i espera'm.» (a la planta baixa)", "o": ["baix", "sota", "davall de"], "e": "Baix vol dir 'en la part baixa' i s'usa normalment sense complement."},
      {"q": "«Va firmar ___ pressió psicològica.»", "o": ["sota", "baix", "davall de"], "e": "Sota s'usa sobretot amb valors figurats de submissió o dependència: sota pressió, sota jurament."},
      {"q": "«Declare ___ jurament que les dades són certes.»", "o": ["sota", "baix", "davall"], "e": "Sota jurament: valor figurat, propi de la preposició sota."},
      {"q": "«Estàvem a tres graus ___ zero.»", "o": ["sota (o per davall de)", "baix de", "baix"], "e": "Per a temperatures: sota zero o per davall de zero."},
      {"q": "Quina frase NO és acceptable?", "o": ["El gos s'ha amagat baix del llit.", "El gos s'ha amagat davall del llit.", "Baix del bancal hi ha una bassa, i dalt, un mas."], "e": "Baix + complement amb valor de davall no és acceptable; sí que ho és amb el valor 'en una part més baixa' (baix del bancal)."},
      {"q": "«Tira-li la carta per ___ la porta.»", "o": ["davall de", "baix de", "debaix de"], "e": "Davall (de): part inferior, amb contacte o sense."},
      {"q": "«El motor pot funcionar ell ___.» (per ell mateix)", "o": ["a soles", "a solas", "en soles"], "e": "Ell sol, ell a soles o per ell mateix."},
      {"q": "«S'ha fet tard; millor si te'n vas tu ___.» (sense companyia)", "o": ["a soles", "solament", "només"], "e": "A soles: sense companyia. Solament i només són adverbis focals ('únicament')."},
      {"q": "Quina forma NO equival a «només»?", "o": ["no més", "sols", "solament"], "e": "Només ('únicament') s'escriu junt; no més és la negació no + el quantitatiu més."},
      {"q": "«Arribeu ___ tard de les nou.» (com a màxim a les nou)", "o": ["no més", "només", "nomes"], "e": "No més tard de: negació + més. Només significa 'únicament'."},
      {"q": "«___ tinc deu euros; no em dona per a l'entrada.»", "o": ["Només", "No més", "Nomes"], "e": "Només = solament, únicament; s'escriu en una paraula i amb accent."},
      {"q": "«Al final ___ hi havia una dotzena de persones.»", "o": ["tan sols", "tant sols", "tan sol"], "e": "Tan sols (o només, sols, solament, únicament)."},
      {"q": "Quina diferència hi ha entre «Ella està sola» i «Sols ella ho sap»?", "o": ["Sola és adjectiu ('sense companyia') i concorda; sols és adverbi ('només') i no varia.", "Totes dues són adverbis invariables.", "Sols és el plural de sola."], "e": "Sol, sola, sols, soles és adjectiu; sols (amb s adverbial) és adverbi sinònim de només."},
      {"q": "«—Vas ser tu? —___, vaig ser jo.» (confirmació)", "o": ["Efectivament", "En absolut", "De cap manera"], "e": "Efectivament (o en efecte) confirma el que s'ha dit."},
      {"q": "«—T'ha molestat el que t'he dit? —___.» (gens, negació rotunda)", "o": ["En absolut", "Sens dubte", "De veres"], "e": "En absolut és una locució de negació; sens dubte i de veres afirmen."},
      {"q": "Escriu en una paraula l'adverbi de dubte: «___ ni se'n recorden.»", "a": ["potser"], "e": "Potser: paraula composta, sense guionet."},
      {"q": "Completa amb el verb en el mode adequat: «Pot ser que ___ (ploure) esta nit.»", "a": ["ploga"], "e": "Pot ser que + subjuntiu: ploga."},
      {"q": "Completa amb el verb en indicatiu (registre formal): «Possiblement ___ (arribar, ells) demà.»", "a": ["arribaran", "arriben"], "e": "Amb els adverbis de dubte, l'indicatiu és el mode tradicional."},
      {"q": "Completa la coordinació mantenint el sufix en tots dos: «Ho va explicar clarament i ___.» (concís)", "a": ["concisament"], "e": "Concisa → concisament; hui és més habitual mantindre -ment en tots dos."},
      {"q": "Escriu l'adverbi (part inferior, amb complement): «Berenarem ___ d'una carrasca.»", "a": ["davall"], "e": "Davall d'una carrasca (o sota una carrasca)."},
      {"q": "Completa la resposta negativa amb la paraula adequada: «—Quant d'arròs et pose? —___.»", "a": ["gens", "no gens"], "e": "Gens (o no gens) amb noms no comptables."},
      {"q": "Escriu en una paraula l'adverbi equivalent a 'únicament': «Ha vingut ___ Joan.»", "a": ["només", "sols", "solament", "únicament"], "e": "Només (o sols, solament, únicament)."}
    ]
  },
  {
    "id": "4aafe8df-63f7-5972-b202-f92737c8162b", "type": "c1_mor_conjuncions", "sort_order": 11,
    "title": "Conjuncions: precisió i registre formal", "name": "Per què / perquè / per a què, causals i consecutives, sinó / si no i locucions condicionals",
    "content": "Precisió en l'ús de les conjuncions i locucions conjuntives i alternatives als usos impropis del valencià formal: distinció entre per què, perquè, per a què i el perquè; usos formals de les causals i les consecutives (doncs); la conjunció adversativa sinó i la condicional negativa si no; i les locucions conjuntives condicionals (sempre que, a condició que, amb la condició que, en cas que) (3.2.2).", "icon": "🧷", "color": "#D1C4E9",
    "exercises": [
      {"q": "«—___ no vas vindre ahir? —Perquè estava malalt.»", "o": ["Per què", "Perquè", "Per a què"], "e": "Per preguntar la causa s'usa l'interrogatiu per què (preposició + què, separat i amb accent)."},
      {"q": "«—Per què no vas vindre ahir? —___ estava malalt.»", "o": ["Perquè", "Per què", "Per a que"], "e": "En la resposta, la causa s'introduïx amb la conjunció perquè, junta."},
      {"q": "«Vull saber ___ has arribat tan tard.» (interrogativa indirecta)", "o": ["per què", "perquè", "per a què"], "e": "Les interrogatives indirectes de causa també porten per què, separat: vull saber per què..."},
      {"q": "«No arribí a entendre ___ de la seua dimissió.»", "o": ["el perquè", "el per què", "el per a què"], "e": "Precedit d'article, perquè es substantiva (= el motiu) i s'escriu junt: el perquè."},
      {"q": "«Els motius ___ ha dimitit no són clars.»", "o": ["per què", "perquè", "per a què"], "e": "Ací què és relatiu precedit de la preposició per (= pels quals): els motius per què ha dimitit."},
      {"q": "Quina expressió equival a «la raó per què ho va fer»?", "o": ["la raó per la qual ho va fer", "la raó perquè ho va fer", "la raó per a la qual ho va fer"], "e": "El relatiu tònic què darrere de preposició es pot substituir per article + qual: per què = per la qual."},
      {"q": "«___ vols el martell?» (pregunta per la finalitat)", "o": ["Per a què", "Per què", "Perquè"], "e": "Per preguntar per la finalitat: preposició per a + interrogatiu què."},
      {"q": "«No em va dir ___ servia tot allò.»", "o": ["per a què", "perquè", "per a que"], "e": "Servir per a alguna cosa: la interrogativa indirecta es fa amb per a què, amb accent (GNV 34.5.5)."},
      {"q": "Quina oració és adequada en un registre formal?", "o": ["S'ha enviat la circular perquè tothom n'estiga informat.", "S'ha enviat la circular per a que tothom n'estiga informat.", "S'ha enviat la circular per què tothom n'estiga informat."], "e": "La conjunció final dels registres formals és perquè; per a que és pròpia de la llengua col·loquial."},
      {"q": "En «Li he deixat els apunts perquè puga estudiar», la conjunció perquè és...", "o": ["final, i per això el verb va en subjuntiu", "causal, i per això el verb va en subjuntiu", "un substantiu"], "e": "Perquè + subjuntiu expressa finalitat; perquè + indicatiu (perquè pot estudiar) expressaria causa."},
      {"q": "«Han analitzat l'aigua ___ els veïns beguen tranquils.»", "o": ["a fi que", "a fi de que", "per a fi que"], "e": "Davant de la conjunció que cau la preposició: a fi de + infinitiu, però a fi que + oració."},
      {"q": "«—Dius que plourà? —___ agafa el paraigua.»", "o": ["Doncs", "Perquè", "Ja que"], "e": "Doncs és consecutiu: introduïx el que es deriva del que s'ha dit abans."},
      {"q": "«No vaig eixir de casa, ___ estava malalt.» (causa)", "o": ["ja que", "doncs", "així que"], "e": "Per a introduir una causa: perquè, ja que, atés que... La GVB classifica doncs entre les consecutives, no entre les causals."},
      {"q": "Quina oració usa «doncs» d'acord amb el valor que li dona la GVB?", "o": ["Has acabat la faena? Doncs ja te'n pots anar.", "No vaig anar a la festa, doncs estava cansat.", "Va arribar tard, doncs hi havia molt de trànsit."], "e": "Doncs és consecutiu (= per tant, aleshores). En les altres dues, amb valor causal, caldria perquè o ja que."},
      {"q": "«Ja ho sabem tots, ___ no cal que ho tornes a contar.»", "o": ["de manera que", "doncs que", "perquè"], "e": "De manera que introduïx la conseqüència del que s'ha dit abans."},
      {"q": "«___ venen temps difícils, haurem de preparar-nos.» (registre culte)", "o": ["Puix que", "Doncs", "Pues"], "e": "Puix que és una locució causal de registre culte (= ja que). Doncs és consecutiu i pues és un castellanisme."},
      {"q": "«Es preveu molta assistència a l'acte, ___ se n'ha fet molta publicitat.»", "o": ["donat que", "així que", "de manera que"], "e": "Donat que és causal (= ja que). Així que i de manera que introduïxen conseqüències."},
      {"q": "Quina conjunció causal es percep com a molt formal i té un ús restringit als àmbits literaris?", "o": ["car", "ja que", "com que"], "e": "La GNV assenyala que car té en l'actualitat un ús molt restringit, propi dels àmbits literaris."},
      {"q": "«No has de parlar amb este advocat, ___ amb l'altre.»", "o": ["sinó", "si no", "sino"], "e": "Sinó (junt i amb accent) té valor substitutiu: afirma del segon element el que es nega del primer."},
      {"q": "«___ aproves, no vindràs de viatge.»", "o": ["Si no", "Sinó", "Si bé"], "e": "Si no (separat) és la conjunció condicional si + l'adverbi de negació no."},
      {"q": "«No t'he dit que calles, ___ parles més baixet.»", "o": ["sinó que", "si no que", "sinó"], "e": "Quan sinó encapçala una oració amb verb conjugat va seguit de que: sinó que."},
      {"q": "«Pots vindre a les deu; ___, a les onze.» (= i en cas contrari)", "o": ["si no", "sinó", "si bé"], "e": "Si no (separat) equival ací a 'en cas contrari': és la condicional negativa amb el verb elidit."},
      {"q": "«Qui ___ tu m'ho podia haver dit?»", "o": ["sinó", "si no", "sino"], "e": "Sinó, junt, significa 'excepte, llevat de': qui sinó tu?"},
      {"q": "«T'ho diré ___ et comprometes a callar.»", "o": ["sempre que", "sempre i quan", "mentre que"], "e": "Sempre que + subjuntiu té valor condicional. *Sempre i quan és un calc del castellà; mentre que és adversatiu."},
      {"q": "«Els ho confessà amb la condició que no ho ___ a ningú.» (contar, ells)", "o": ["contaren", "contaven", "conten"], "e": "Les locucions condicionals com amb la condició que porten subjuntiu; amb un verb principal en passat, imperfet de subjuntiu."},
      {"q": "«Ens deixaran entrar a la sala ___ no fem fotografies.»", "o": ["a condició que", "a condició de que", "en condició que"], "e": "Davant de que cau la preposició de: a condició de + infinitiu, però a condició que + oració."},
      {"q": "«Pots demanar un certificat ___ el necessites.»", "o": ["en cas que", "en cas de que", "a cas que"], "e": "En cas de + nom o infinitiu, però en cas que + oració: la preposició de cau davant de que."},
      {"q": "«___ vinga, farem festa.» (suposant que vinga)", "o": ["Posat que", "Posat de que", "Pose que"], "e": "Posat que és una locució conjuntiva condicional: posat que vinga = suposant que vinga."},
      {"q": "«___ Neus parle, tot s'aclarirà.» (n'hi ha prou que parle)", "o": ["Amb que", "Amb què", "Per a que"], "e": "Amb que (sense accent) és condicional: n'hi ha prou que es complisca la condició."},
      {"q": "«No eixirem ___ pare de ploure.» (llevat que)", "o": ["a menys que", "sinó", "si bé"], "e": "A menys que + subjuntiu és una locució condicional negativa (= llevat que, si no)."},
      {"q": "«Si ___ temps, ens veurem demà.» (tindre, jo)", "o": ["tinc", "tinga", "tindré"], "e": "La conjunció si de les condicionals reals va amb indicatiu, mai amb present de subjuntiu ni amb futur."},
      {"q": "«Si ho ___ tot, me n'aniria d'acampada amb els amics.» (aprovar, jo)", "o": ["aprovara", "aprovaria", "aprove"], "e": "Condicional irreal: imperfet de subjuntiu en la condició i condicional en la principal."},
      {"q": "«Si m'ho ___ dit abans, t'hauria ajudat.»", "o": ["hagueres", "hauries", "havies"], "e": "Condicional irreal de passat: plusquamperfet de subjuntiu (hagueres dit) i condicional perfet (hauria ajudat)."},
      {"q": "«___ el veig, em saluda.» (cada vegada que)", "o": ["Sempre que", "Sempre i quan", "Mentre que"], "e": "Amb indicatiu, sempre que té valor temporal de freqüència (= cada vegada que)."},
      {"q": "Escriu l'interrogatiu: «—___ has tardat tant? —Perquè hi havia trànsit.»", "a": ["per què"], "e": "Pregunta per la causa: per què, separat i amb accent."},
      {"q": "Escriu l'expressió substantivada (amb article): «Ningú no m'ha explicat ___ d'esta decisió.»", "a": ["el perquè"], "e": "El perquè = el motiu: s'escriu junt."},
      {"q": "Escriu el relatiu (= per les quals): «Les raons ___ ho va deixar eren personals.»", "a": ["per què"], "e": "Preposició + relatiu tònic què: per què (= per les quals)."},
      {"q": "Escriu l'interrogatiu de finalitat: «___ servix este aparell?»", "a": ["per a què"], "e": "Finalitat: per a + què."},
      {"q": "Completa amb «sinó» o «si no»: «No vull té, ___ café.»", "a": ["sinó"], "e": "Sinó substituïx l'element negat."},
      {"q": "Completa amb dues paraules (= en cas contrari): «Has de presentar el treball; ___, suspendràs.»", "a": ["si no"], "e": "Si no, separat: condició negativa."},
      {"q": "Escriu la locució condicional (a ... que): «Te'l deixe ___ me'l tornes demà.»", "a": ["a condició que", "amb la condició que"], "e": "A condició que (o amb la condició que) + subjuntiu, sense la preposició de davant de que."},
      {"q": "Escriu el connector consecutiu d'una paraula: «Dius que tens fred? ___ tanca la finestra.»", "a": ["doncs"], "e": "Doncs introduïx una conseqüència del que s'ha dit."},
      {"q": "Escriu la conjunció final pròpia del registre formal: «Parla més alt ___ t'entenguen.»", "a": ["perquè"], "e": "Finalitat en registre formal: perquè + subjuntiu (no per a que)."},
      {"q": "Escriu la locució causal culta (dues paraules, comença per p-): «___ venen temps difícils, estalviem.»", "a": ["puix que"], "e": "Puix que = ja que, en registre culte."}
    ]
  },
  {
    "id": "f7396f19-430b-5930-99f6-8f9d44adc025", "type": "c1_mor_connectors", "sort_order": 12,
    "title": "Connectors i cohesió del discurs", "name": "Ordenació, addició, contrast, reformulació, exemplificació, conseqüència i conclusió, i calcs que cal evitar",
    "content": "Ús dels connectors com a mecanisme de cohesió discursiva: connectors distributius i lògics d'addició, de contrast, de reformulació, d'exemplificació, de conseqüència, de resum i de conclusió, i alternatives genuïnes als calcs més freqüents (per lo tant, de lo contrari, sin embargo, a nivell de, en base a) (3.2.2).", "icon": "🪢", "color": "#B2EBF2",
    "exercises": [
      {"q": "«___, analitzarem les causes; en segon lloc, les conseqüències.»", "o": ["En primer lloc", "En lloc primer", "Al primer lloc"], "e": "Connector d'ordenació del discurs: en primer lloc, en segon lloc, per últim (o primerament, finalment)."},
      {"q": "«D'una banda, el projecte és car; ___, és molt necessari.»", "o": ["d'altra banda", "d'altre lado", "a l'altra part"], "e": "La correlació distributiva és d'una banda... d'altra banda."},
      {"q": "«___ per un motiu, ___ per un altre, el cas és que no ho ha fet.»", "o": ["Ja... ja", "Sinó... sinó", "Doncs... doncs"], "e": "Construcció distributiva paral·lela: ja... ja (com ara... ara, bé... bé, siga... siga)."},
      {"q": "«Ha de reforçar l'empresa, ___ ampliant el patrimoni, ___ facilitant la fusió.»", "o": ["bé... bé", "ni... ni", "tan... com"], "e": "Bé... bé presenta alternatives en construcció paral·lela."},
      {"q": "«El pis és cèntric i, ___, té molta llum.»", "o": ["a més", "encima", "ademés"], "e": "Connector d'addició: a més. Encima i ademés són castellanismes."},
      {"q": "«Recordem, ___, que en este establiment no es permet fumar.»", "o": ["igualment", "en canvi", "per contra"], "e": "Igualment (com així mateix o paral·lelament) establix una equiparació amb el que s'ha dit."},
      {"q": "Quin valor té «així mateix» en «Es va produir, així mateix, una solsida de terres»?", "o": ["equiparació o addició", "oposició", "conseqüència"], "e": "Així mateix afig una informació equiparable a l'anterior (GVB 38.3)."},
      {"q": "«El pressupost és ajustat; ___, el projecte tira avant.»", "o": ["no obstant això", "sin embargo", "no obstant de"], "e": "Contrast: no obstant això (o això no obstant, tanmateix). Sin embargo és un castellanisme."},
      {"q": "Quin d'estos connectors és un castellanisme que cal evitar?", "o": ["sin embargo", "tanmateix", "així i tot"], "e": "Tanmateix i així i tot són connectors de contrast genuïns; sin embargo és un barbarisme."},
      {"q": "«La pel·lícula dura tres hores; ___, no es fa llarga.»", "o": ["amb tot", "per tant", "és a dir"], "e": "Amb tot és un connector de contrast (= no obstant això). Per tant és consecutiu i és a dir, de reformulació."},
      {"q": "«La teua proposta és bona. ___, caldrà revisar-ne el cost.»", "o": ["Ara bé", "Bueno", "Pues bé"], "e": "Ara bé introduïx una restricció al que s'ha dit. Bueno i pues són castellanismes."},
      {"q": "Quina oració està ben puntuada?", "o": ["No ha estudiat gens i, no obstant això, ha aprovat.", "No ha estudiat gens i no obstant això ha aprovat.", "No ha estudiat gens, i no obstant això, ha aprovat."], "e": "Els connectors parentètics com no obstant això van entre comes (GVB 15.3.1)."},
      {"q": "«És plurilingüe, ___, parla més de dues llengües.»", "o": ["és a dir", "per exemple", "en canvi"], "e": "És a dir introduïx una reformulació o aclariment del que s'ha dit."},
      {"q": "«___, no hi ha diners per a tot.» (dit d'una altra manera)", "o": ["En altres paraules", "En otres paraules", "A altres paraules"], "e": "Connector de reformulació: en altres paraules (o és a dir, dit d'una altra manera)."},
      {"q": "«Vindrà la setmana que ve, ___, dilluns o dimarts.»", "o": ["o siga", "osea", "lo que és"], "e": "O siga és un connector de reformulació (= és a dir)."},
      {"q": "«Hi ha fruites tropicals, ___ el mango o la papaia.»", "o": ["com ara", "tal que", "a nivell de"], "e": "Com ara introduïx exemples. *A nivell de és un calc que cal evitar."},
      {"q": "«Molts animals hivernen; l'os, ___, dorm durant mesos.»", "o": ["per exemple", "en conclusió", "tanmateix"], "e": "Per exemple introduïx un cas concret del que s'ha dit en general."},
      {"q": "«Imagina, ___, que perds el passaport.»", "o": ["posem per cas", "per lo tant", "a lo millor"], "e": "Posem per cas és un connector d'exemplificació. Per lo tant i a lo millor són calcs amb l'article neutre."},
      {"q": "«Les pluges han provocat el caos, ___ en les zones costaneres.»", "o": ["sobretot", "sobretodo", "sobre todo"], "e": "Sobretot (una paraula) especifica o remarca un aspecte del discurs."},
      {"q": "«És un acte il·legal i, ___, ha de ser declarat nul.»", "o": ["per consegüent", "sin embargo", "en canvi"], "e": "Per consegüent (o consegüentment, en conseqüència) indica una conseqüència."},
      {"q": "«___, et toca substituir-lo a tu.»", "o": ["Per tant", "Per lo tant", "Pel tant"], "e": "La GVB rebutja per lo tant: el connector consecutiu és per tant."},
      {"q": "«Va presentar la sol·licitud fora de termini; ___, no li han concedit l'ajuda.»", "o": ["en conseqüència", "en consecuència", "a conseqüència de"], "e": "En conseqüència és un connector consecutiu. A conseqüència de és una locució preposicional seguida de nom."},
      {"q": "«—No tinc ganes d'anar-hi. —___ queda't a casa.»", "o": ["Doncs", "Pues", "Puix"], "e": "Doncs és el connector consecutiu genuí; pues és un castellanisme i puix és causal."},
      {"q": "«___, el curs ha sigut un èxit.» (per a tancar)", "o": ["En definitiva", "En base a tot", "A nivell general"], "e": "En definitiva és un connector de conclusió. *En base a i *a nivell de són calcs."},
      {"q": "«___, podem dir que l'experiment ha funcionat.»", "o": ["En conclusió", "En conclusió de", "Concluint de"], "e": "En conclusió, en definitiva o per acabar tanquen el discurs."},
      {"q": "«Per a concloure, ___ que estem molt satisfets de la participació.»", "o": ["hem de dir", "dir", "dient"], "e": "No és recomanable l'infinitiu com a verb principal de recapitulació (*Per a concloure, dir que...*): cal un verb conjugat (GNV 28.6.2)."},
      {"q": "«___, després de tantes voltes, va acceptar la proposta.»", "o": ["Al cap i a la fi", "Al final de cuentes", "A la fi i al cap"], "e": "Al cap i a la fi és un connector de conclusió (= en definitiva)."},
      {"q": "«Va arribar la policia i ___ tots van fugir.»", "o": ["aleshores", "entonces", "antonces"], "e": "Aleshores (o llavors) és el connector temporal genuí; entonces és un castellanisme."},
      {"q": "«___, el ponent va respondre les preguntes del públic.»", "o": ["A continuació", "A continuació de", "Seguidament de"], "e": "A continuació (o tot seguit, seguidament) ordena el discurs sense complement."},
      {"q": "«___, sol ser molt puntual.»", "o": ["Generalment", "Per lo general", "Pel general"], "e": "La GVB rebutja per lo general i proposa generalment (o en general)."},
      {"q": "«___, és un xicon molt agradable.» (deixant a banda el que s'ha dit)", "o": ["D'altra banda", "Per lo demés", "Pel demés"], "e": "Per lo demés és un calc: la GVB proposa d'altra banda o això a banda."},
      {"q": "«Has de fer el treball; ___, suspendràs.»", "o": ["altrament", "de lo contrari", "a lo contrari"], "e": "De lo contrari és un calc: la GVB proposa si no, d'una altra manera o altrament."},
      {"q": "«___ les seues declaracions, no hi ha res a afegir.»", "o": ["Pel que fa a", "En lo referent a", "En quant a"], "e": "La GVB rebutja en lo referent a i proposa respecte a, pel que fa a o quant a (no *en quant a)."},
      {"q": "Quina oració és adequada en un registre formal?", "o": ["Pel que fa a l'economia, el país ha millorat.", "A nivell d'economia, el país ha millorat.", "A nivell econòmic, el país ha millorat."], "e": "*A nivell de amb el valor de 'pel que fa a' és un calc: usa pel que fa a, quant a o en l'àmbit de."},
      {"q": "«La decisió es va prendre ___ els informes tècnics.»", "o": ["a partir de", "en base a", "a base a"], "e": "*En base a és un calc del castellà: usa a partir de, sobre la base de o basant-se en."},
      {"q": "Escriu el connector de reformulació (tres paraules): «Arribarà a migdia, ___, a les dotze.»", "a": ["és a dir"], "e": "És a dir introduïx una reformulació."},
      {"q": "Substituïx «per lo tant» pel connector correcte: «Ha plogut molt; ___, s'ajorna el partit.»", "a": ["per tant", "per consegüent", "en conseqüència", "consegüentment"], "e": "Per tant (o per consegüent, en conseqüència)."},
      {"q": "Substituïx «per lo general» per un adverbi en -ment: «___, sol arribar puntual.»", "a": ["generalment"], "e": "Generalment (o en general)."},
      {"q": "Substituïx «de lo contrari»: «Afanya't; ___, perdrem el tren.»", "a": ["altrament", "si no", "d'una altra manera", "en cas contrari"], "e": "Altrament, si no o d'una altra manera."},
      {"q": "Substituïx «en base a»: «Hem decidit ___ les dades disponibles.»", "a": ["a partir de", "sobre la base de", "d'acord amb"], "e": "A partir de o sobre la base de, mai *en base a."},
      {"q": "Substituïx «sin embargo» per un connector d'una sola paraula: «És car; ___, el comprarem.»", "a": ["tanmateix"], "e": "Tanmateix = no obstant això."},
      {"q": "Escriu el connector d'exemplificació (dues paraules, comença per c-): «Toca diversos instruments, ___ el piano o la guitarra.»", "a": ["com ara"], "e": "Com ara introduïx exemples."},
      {"q": "Escriu el connector de conclusió (dues paraules, comença per en d-): «___, ha sigut un any excel·lent.»", "a": ["en definitiva"], "e": "En definitiva tanca o resumix el discurs."},
      {"q": "Substituïx «per lo menys» per un adverbi: «___, ha donat un descàrrec.»", "a": ["almenys"], "e": "La GVB proposa almenys en lloc de per lo menys."},
      {"q": "Substituïx «en lo referent a» per una locució de tres paraules: «___ la normativa, no hi ha canvis.»", "a": ["pel que fa a"], "e": "Pel que fa a (o respecte a, quant a)."}
    ]
  },
  {
    "id": "152bfa62-d3c1-5a12-bb0d-7c424cc042f5", "type": "c1_mor_verbs_irregulars", "sort_order": 13,
    "title": "Verbs irregulars i verbs amb interferències", "name": "Velaritzats, verbs en -metre, -córrer, -fondre, -batre, -rompre i -cloure, i cabre, caldre, saber i veure",
    "content": "Conjugació dels verbs irregulars velaritzats i dels verbs que presenten interferències en la conjugació (admetre, concebre, ocórrer, garantir, telefonar, trair, rebre, percebre, florir), inclosos els acabats en -metre, -córrer, -fondre, -batre, -rompre i -cloure, i remarques sobre la conjugació irregular de cabre, caldre, saber i veure o vore (3.2.2).", "icon": "⚙️", "color": "#FFCCBC",
    "exercises": [
      {"q": "«Espere que ___ a temps a la reunió.» (vindre, ell)", "o": ["vinga", "venga", "vinguera"], "e": "Present de subjuntiu velaritzat: vinga, vingues, vinga, vinguem, vingueu, vinguen."},
      {"q": "«Li vaig demanar que ___ paciència.» (tindre, ell)", "o": ["tinguera", "tenguera", "tenira"], "e": "Amb el verb principal en passat, imperfet de subjuntiu, també velaritzat: tinguera."},
      {"q": "«Les seues paraules m'han ___ molt.» (doldre)", "o": ["dolgut", "dolt", "dolit"], "e": "Els verbs en -ldre fan el participi en -t (resolt, molt), però doldre i oldre fan dolgut i olgut."},
      {"q": "«Estava ___ la veritat i no el van creure.» (dir)", "o": ["dient", "diguent", "dint"], "e": "Cap gerundi amb increment velar és acceptable: dient, venint, vivint (no *diguent, *vinguent, *visquent)."},
      {"q": "«El reglament no ___ excepcions.» (admetre, present)", "o": ["admet", "admitix", "admiteix"], "e": "Admetre es conjuga com batre: admet, admets, admet, admetem, admeteu, admeten. *Admitir és un castellanisme."},
      {"q": "«Espere que el tribunal ___ el recurs.» (admetre, subjuntiu)", "o": ["admeta", "admitisca", "admetisca"], "e": "Present de subjuntiu valencià en -a: admeta, admetes, admeta..."},
      {"q": "«Encara no s'han ___ més sol·licituds.» (admetre)", "o": ["admés", "admitit", "admetut"], "e": "Els verbs en -metre fan el participi en -és: admés, admesa, admesos, admeses."},
      {"q": "«No està ___ fumar en el recinte.» (permetre)", "o": ["permés", "permitit", "permetut"], "e": "Permetre → permés (com admés, comés, promés)."},
      {"q": "«La cadena ha ___ el partit en directe.» (transmetre)", "o": ["transmés", "transmitit", "transmetut"], "e": "Transmetre → transmés: tots els verbs en -metre tenen participi sigmàtic."},
      {"q": "«No ___ que ho haja fet ell.» (concebre, jo, present)", "o": ["concep", "concebisc", "concibo"], "e": "Concebre es conjuga com rebre: concep, conceps, concep, concebem, concebeu, conceben."},
      {"q": "«Quan ___ la carta, avisa'm.» (rebre, tu, subjuntiu)", "o": ["rebes", "rebixes", "recibisques"], "e": "Rebre no és incoatiu: present de subjuntiu reba, rebes, reba, rebem, rebeu, reben."},
      {"q": "«Este mes encara no ___ el sou.» (rebre, jo, perfet)", "o": ["he rebut", "he rebit", "he recibit"], "e": "El participi de rebre és rebut (com concebut i percebut)."},
      {"q": "«Cada mes ___ una subvenció de l'ajuntament.» (percebre, ells)", "o": ["perceben", "percibixen", "percebixen"], "e": "Percebre: percep, perceps, percep, percebem, percebeu, perceben."},
      {"q": "«No crec que li ___ res greu.» (ocórrer, subjuntiu)", "o": ["ocórrega", "ocorra", "ocurrisca"], "e": "Ocórrer es conjuga com córrer: present de subjuntiu ocórrega, ocórregues..."},
      {"q": "«Al concurs hi han ___ més de cent persones.» (concórrer)", "o": ["concorregut", "concurrit", "concorrut"], "e": "Els derivats de córrer fan el participi corregut: concorregut, incorregut, discorregut."},
      {"q": "«Espere que no ___ en el mateix error.» (incórrer, tu)", "o": ["incórregues", "incorres", "incurrisques"], "e": "Present de subjuntiu velaritzat: incórrega, incórregues... (com córregues)."},
      {"q": "«M'he ___ de carpeta i he obert la que no era.» (confondre)", "o": ["confós", "confundit", "confongut"], "e": "Els verbs en -ndre fan el participi en -s: fondre → fos; confondre → confós (amb o tancada)."},
      {"q": "«La notícia s'ha ___ ràpidament per les xarxes.» (difondre)", "o": ["difós", "difundit", "difòs"], "e": "Difondre → difós, difosa: o tancada, accent agut."},
      {"q": "«No ___ els noms: tu eres Pau i ell Pere.» (confondre, jo, present)", "o": ["confonc", "confundisc", "confongo"], "e": "Confondre és velaritzat en la primera persona: confonc, confons, confon, confonem, confoneu, confonen."},
      {"q": "«L'exèrcit ha ___ l'enemic durant mesos.» (combatre)", "o": ["combatut", "combatit", "combatés"], "e": "Els derivats de batre són regulars de la segona conjugació: combatut, debatut, abatut."},
      {"q": "«El Parlament ___ ara la llei de pressupostos.» (debatre, present)", "o": ["debat", "debatix", "debateix"], "e": "Debatre es conjuga com batre, no com un incoatiu: debat, debats, debat..."},
      {"q": "«No m'___ quan parle!» (interrompre, tu)", "o": ["interrompes", "interrumpixes", "interrompisques"], "e": "L'imperatiu negatiu usa el present de subjuntiu: interrompa, interrompes..."},
      {"q": "«La sessió s'ha ___ per un problema tècnic.» (interrompre)", "o": ["interromput", "interrumpit", "interrompit"], "e": "Els verbs en -rompre fan el participi en -ut: romput, interromput, corromput."},
      {"q": "«El poder l'ha ___.» (corrompre)", "o": ["corromput", "corrupte", "corrumpit"], "e": "Corromput és el participi; corrupte és un adjectiu (un polític corrupte)."},
      {"q": "«Ja has ___ el treball de fi de grau?» (concloure)", "o": ["conclòs", "conclós", "concloït"], "e": "Els verbs en -cloure fan el participi en -s amb o oberta: conclòs, inclòs, exclòs."},
      {"q": "«Abans, el preu ___ l'IVA.» (incloure, imperfet)", "o": ["incloïa", "incloia", "inclouia"], "e": "Imperfet d'incloure: incloïa, incloïes, incloïa, incloíem, incloíeu, incloïen."},
      {"q": "«L'empresa ___ la qualitat del producte.» (garantir, present)", "o": ["garantix", "garantiza", "garanta"], "e": "Garantir és incoatiu: garantisc, garantixes, garantix, garantim, garantiu, garantixen."},
      {"q": "«A la primavera els ametlers ___.» (florir, present)", "o": ["florixen", "floren", "florecixen"], "e": "Florir és incoatiu: florisc, florixes, florix, florim, floriu, florixen."},
      {"q": "«Espere que em ___ prompte.» (telefonar, tu)", "o": ["telefones", "telefonees", "telefonejes"], "e": "Telefonar és un verb regular de la primera conjugació: telefone, telefones, telefone..."},
      {"q": "«Si continua així, et ___.» (trair, futur)", "o": ["trairà", "traïrà", "traurà"], "e": "El futur i el condicional dels verbs en vocal + -ir no porten dièresi: trairà, com agrairà."},
      {"q": "«Ell mai no ___ els amics.» (trair, imperfet)", "o": ["traïa", "traia", "traiïa"], "e": "Imperfet de trair: traïa, amb dièresi perquè la i no forma diftong (com agraïa)."},
      {"q": "«En esta maleta ja no hi ___ res més.» (cabre, present)", "o": ["cap", "cab", "cabe"], "e": "Cabre: present cap (3a persona), cabem, cabeu, caben."},
      {"q": "«Per a la mudança ___ tres persones més.» (caldre, present)", "o": ["calen", "cal", "calguen"], "e": "Caldre concorda amb el subjecte: calen tres persones; amb un infinitiu o una oració, cal."},
      {"q": "«Vull que ___ la veritat.» (saber, tu)", "o": ["sàpies", "sapies", "sabes"], "e": "Present de subjuntiu de saber: sàpia, sàpies, sàpia, sapiem, sapieu, sàpien."},
      {"q": "«Ara ___ la pel·lícula tots junts.» (veure, present, nosaltres)", "o": ["veiem", "vegem", "veguem"], "e": "La persona 4 del present de veure és veiem; vegem és subjuntiu (GNV 30.2.4.2)."},
      {"q": "Escriu el participi masculí singular de «admetre».", "a": ["admés"], "e": "Admés, amb é tancada."},
      {"q": "Escriu el participi masculí singular de «concloure».", "a": ["conclòs"], "e": "Conclòs, amb ò oberta."},
      {"q": "Escriu el participi masculí singular de «interrompre».", "a": ["interromput"], "e": "Interromput."},
      {"q": "Escriu la tercera persona del singular del present de «rebre»: ell ___.", "a": ["rep"], "e": "Rep (rebre no és incoatiu)."},
      {"q": "Escriu el present de subjuntiu de «garantir» per a «ell»: «Cal que ho ___.»", "a": ["garantisca"], "e": "Garantisca: incoatiu amb -isc-."},
      {"q": "Escriu el participi masculí singular de «difondre».", "a": ["difós"], "e": "Difós."},
      {"q": "Escriu el participi de «incórrer».", "a": ["incorregut"], "e": "Incorregut, com corregut."},
      {"q": "Escriu el present de subjuntiu de «saber» per a «jo»: «No crec que ho ___.»", "a": ["sàpia"], "e": "Sàpia."},
      {"q": "Escriu el gerundi de «veure».", "a": ["veient", "veent"], "e": "Veient (o veent), mai *vegent."},
      {"q": "Escriu l'imperfet de subjuntiu de «caldre» (3a persona): «Si ___, t'ajudaria.»", "a": ["calguera"], "e": "Caldre fa l'imperfet de subjuntiu velaritzat: calguera."}
    ]
  },
  {
    "id": "25bb9509-8872-50b3-a3ff-33491658da81", "type": "c1_mor_verbs_formes", "sort_order": 14,
    "title": "Morfologia verbal formal i variació", "name": "Formes poc usuals d'irregulars, model pur i incoatiu, formes no velaritzades i desinències d'altres parlars",
    "content": "Ús de la morfologia verbal adequada als contextos formals: formes poc usuals de verbs irregulars (complaure, cruixir, escopir, fondre, imprimir, jaure, lluir, moldre, morir, oir, romandre, rostir), conjugació dels verbs que admeten el model pur i l'incoatiu (afig/afegix), formes sense velaritzar dels verbs de la segona i la tercera conjugacions en el present d'indicatiu, el present de subjuntiu i l'imperatiu (dorm, perd, sent; dorma, perda, senta), i variació diatòpica de les desinències verbals (cante = canto = cant = canti) (3.2.2).", "icon": "🧬", "color": "#DCEDC8",
    "exercises": [
      {"q": "«Em ___ presentar-vos el nou director.» (complaure, present, ell)", "o": ["complau", "complaix", "complaeix"], "e": "Complaure es conjuga com plaure: complac, complaus, complau, complaem, complaeu, complauen."},
      {"q": "«La vostra visita m'ha ___ molt.» (complaure)", "o": ["complagut", "complaït", "complaust"], "e": "Complaure fa el participi velaritzat: complagut (com plagut)."},
      {"q": "«Cal que el ferrer ___ el metall a alta temperatura.» (fondre)", "o": ["fonga", "fona", "fondisca"], "e": "Fondre és velaritzat: fonc, fonga, fonguera, i participi fos."},
      {"q": "«Estaven ___ el plom en un gresol.» (fondre)", "o": ["fonent", "fonguent", "fonint"], "e": "Cap gerundi porta increment velar: fonent, com batent."},
      {"q": "«Els cartells ja estan ___.» (imprimir)", "o": ["impresos", "impressos", "imprimuts"], "e": "Imprimir té participi sigmàtic: imprés, impresa, impresos, impreses (amb una sola s)."},
      {"q": "«El gos ___ tot el dia davall de la taula.» (jaure, imperfet)", "o": ["jeia", "jaïa", "jaia"], "e": "Jaure té imperfet fort, com fer, caure o traure: jeia, jeies, jeia... (GNV 30.2.4.1)."},
      {"q": "«Quan estic malalt, ___ al llit tot el dia.» (jaure, jo)", "o": ["jac", "jau", "jaig"], "e": "Jaure és velaritzat en la primera persona: jac, jaus, jau."},
      {"q": "«Estava ___ a l'ombra del garrofer.» (jaure)", "o": ["jaient", "jaguent", "jaurint"], "e": "Gerundi amb i consonàntica (jaient, també jaent), mai amb velar (GNV 30.2.4.2)."},
      {"q": "«Este vestit ___ molt.» (lluir, present)", "o": ["lluïx", "lluix", "lluí"], "e": "Lluir és incoatiu i la u i la i fan hiat: lluïx, lluïxen, amb dièresi."},
      {"q": "«El molí ___ el blat cada dijous.» (moldre, present)", "o": ["mol", "molt", "mola"], "e": "Moldre: molc, mols, mol, molem, moleu, molen. La d només apareix davant de r (moldre, moldré)."},
      {"q": "«Ja han ___ tot el cafè.» (moldre)", "o": ["molt", "molgut", "moldut"], "e": "Els verbs en -ldre fan el participi fort en -t: molt, resolt, absolt (GNV 30.2.4.4)."},
      {"q": "«No vull que ningú ___ per culpa d'esta negligència.» (morir, subjuntiu)", "o": ["muira", "muera", "morisca"], "e": "Present de subjuntiu de morir: muira, muires, muira, morim, moriu, muiren."},
      {"q": "«El rosal s'ha ___ amb la sequera.» (morir)", "o": ["mort", "morit", "mòrt"], "e": "Morir té participi fort en -t: mort, morta (GNV 30.2.4.4)."},
      {"q": "«Ningú no ha ___ els seus crits.» (oir)", "o": ["oït", "oit", "oïdo"], "e": "El participi porta dièresi perquè la i no forma diftong amb la o: oït, oïda."},
      {"q": "«Des de casa s'___ la banda del poble.» (oir, imperfet)", "o": ["oïa", "oia", "ouïa"], "e": "Imperfet amb hiat: oïa, oïes, oïa. Sense dièresi, oia es llegiria amb diftong."},
      {"q": "«Els documents han ___ tancats durant anys.» (romandre)", "o": ["romasos", "romanguts", "romandits"], "e": "Els verbs en -ndre (excepte vendre i pondre) tenen participi sigmàtic: romàs, romasa, romasos, romases."},
      {"q": "«Cal que el jurat ___ reunit fins a la decisió.» (romandre)", "o": ["romanga", "romandisca", "romana"], "e": "Romandre és velaritzat: romanc, romanga, romanguera."},
      {"q": "«Qui ___ cap amunt, a la cara li cau.» (escopir, model pur)", "o": ["escup", "escop", "escupix"], "e": "Escopir alterna u tònica / o àtona en el model pur: escup, escopim (GNV 30.2.1)."},
      {"q": "«Mon pare sempre ___ les castanyes en la llar.» (rostir, model pur)", "o": ["rust", "rost", "rusteix"], "e": "Rostir, model pur: rust, rusts, rust, rostim, rostiu, rusten (alternança u/o)."},
      {"q": "«Les bigues han ___ tota la nit.» (cruixir)", "o": ["cruixit", "cruixut", "cruixat"], "e": "Cruixir és de la tercera conjugació: participi cruixit, gerundi cruixint."},
      {"q": "Quines dues formes del present (ell) admet «afegir»?", "o": ["afig / afegix", "afeg / afegix", "afig / afigix"], "e": "Afegir admet el model pur (afig, amb i tònica) i l'incoatiu (afegix)."},
      {"q": "«Vull que hi ___ un poc de sal.» (afegir, tu, model pur)", "o": ["afiges", "afegs", "afigues"], "e": "Subjuntiu pur: afija, afiges, afija, afegim, afegiu, afigen; l'incoatiu seria afegisques."},
      {"q": "«Espere que ell ___ l'informe abans de la reunió.» (llegir, model pur)", "o": ["llija", "llega", "lligga"], "e": "Model pur: llija (incoatiu: llegisca). Lligga és una forma velaritzada col·loquial."},
      {"q": "«Espere que no ___ el tren.» (perdre, tu, registre formal)", "o": ["perdes", "pergues", "perdisques"], "e": "La GNV recomana en l'estàndard el model no velaritzat: perda, perdes; pergues és col·loquial."},
      {"q": "«Quan ___ esta cançó, em pose trist.» (sentir, jo, registre formal)", "o": ["sent", "senc", "sentisc"], "e": "Sentir és el model de la tercera pura: sent, sents, sent (GNV 29.4.4)."},
      {"q": "«L'equip ___ el partit en l'últim minut.» (perdre, passat simple)", "o": ["perdé", "pergué", "perguí"], "e": "Passat simple regular: perdí, perderes, perdé. Pergué és la variant velaritzada col·loquial."},
      {"q": "«___ vosté tranquil·lament, que demà no cal matinar.» (dormir, imperatiu)", "o": ["Dorma", "Dorga", "Dormisca"], "e": "Imperatiu de 3a persona = present de subjuntiu no velaritzat: dorma."},
      {"q": "Segons la GNV, quin valor tenen formes com «dorc», «perga» o «senga»?", "o": ["Són col·loquials; en l'estàndard es preferixen dorm, perda, senta.", "Són les úniques formes correctes en valencià.", "Són castellanismes inacceptables en qualsevol registre."], "e": "El model no velaritzat és el clàssic i el formal; el velaritzat pot reproduir un llenguatge espontani (GNV 30.2.3)."},
      {"q": "Un parlant de Vinaròs diu «Jo canto en el cor». Què cal fer?", "o": ["Res: canto és la forma del valencià septentrional, equivalent a cante.", "Corregir-lo, perquè canto és un castellanisme.", "Corregir-lo, perquè la forma normativa és cant."], "e": "En els parlars més septentrionals la primera persona acaba en -o en totes les conjugacions (GNV 29.5.a)."},
      {"q": "En un text d'un autor mallorquí llegim «jo cant». Què és?", "o": ["La primera persona del present sense vocal final, pròpia dels parlars baleàrics.", "Un imperatiu de segona persona.", "Un error que cal corregir per cante."], "e": "Els parlars baleàrics no han generalitzat la -e: jo cant, jo pens (GNV 29.5.a)."},
      {"q": "En un text de Barcelona: «Vol que jo canti». Què és «canti»?", "o": ["El present de subjuntiu en -i de Catalunya i les Balears, equivalent a cante.", "Un imperfet de subjuntiu.", "Una forma incorrecta que cal esmenar."], "e": "En eixos parlars la i ha substituït la e del subjuntiu: canti, bati, senti (GNV 29.5.f)."},
      {"q": "Quina afirmació sobre «que ell cantés» és correcta?", "o": ["És un imperfet de subjuntiu en -s, equivalent a cantara.", "És un passat simple de cantar.", "És una forma incorrecta en valencià."], "e": "Les formes en -s són pròpies del valencià septentrional i de la resta de l'àmbit lingüístic (GNV 29.5.c)."},
      {"q": "Quina variant de l'increment incoatiu se sent antiga i molt formal i sol evitar-se en l'estàndard?", "o": ["servesc", "servisc", "serveix"], "e": "Servisc és la forma general; serveix és una variant escrita normal; servesc, servesca s'eviten (GNV 29.5.e)."},
      {"q": "En registre formal, quina forma de subjuntiu (nosaltres) de «tindre» es preferix?", "o": ["tinguem", "tingam", "tenim"], "e": "Les formes en -am, -au (tingam, tingau) són vives en parlars valencians, però en el registre formal s'usen tinguem, tingueu (GNV 29.5.f)."},
      {"q": "Quina sèrie mostra la grafia que s'ha generalitzat en l'escriptura actual?", "o": ["nasc, cresc, visc", "naixc, creixc, vixc", "nasco, cresco, visco"], "e": "Encara que sovint es pronuncia palatal, s'escriu -sc, la forma etimològica i clàssica (GNV 29.5.e)."},
      {"q": "«Jo també ho haguera fet, si m'ho hagueren dit.» Què cal dir d'«haguera fet»?", "o": ["És correcte: el condicional perfet admet hauria o haguera.", "És incorrecte: només s'admet hauria fet.", "Haguera només pot ser plusquamperfet de subjuntiu."], "e": "L'auxiliar del condicional perfet pot adoptar formes en -ria o en -ra (GNV 29.5.b)."},
      {"q": "Escriu el participi de «jaure».", "a": ["jagut"], "e": "Jaure és velaritzat també en el participi: jagut."},
      {"q": "Escriu el participi masculí singular de «romandre».", "a": ["romàs"], "e": "Romàs, amb a oberta: romàs, romasa, romasos, romases."},
      {"q": "Escriu el participi masculí singular de «imprimir».", "a": ["imprés"], "e": "Imprés: participi sigmàtic recollit en la GNV (30.2.4.4)."},
      {"q": "Escriu el present de subjuntiu de «moldre» (jo): «Vol que ___ el gra abans de dinar.»", "a": ["molga"], "e": "Moldre és velaritzat: molc, molga, molgues..."},
      {"q": "Escriu el present de subjuntiu incoatiu de «afegir» (ell): «Cal que hi ___ una clàusula.»", "a": ["afegisca"], "e": "Incoatiu: afegisca; el pur seria afija."},
      {"q": "Escriu la forma no velaritzada (formal): «No vull que ___ el temps.» (perdre, ell)", "a": ["perda"], "e": "Perda, perdes, perda...: el model regular és el que convé en l'estàndard."},
      {"q": "Escriu la primera persona del present de «dormir» en registre formal: «Jo ___ poc.»", "a": ["dorm"], "e": "Dorm (no dorc), segons el model de sentir."},
      {"q": "Escriu la forma del valencià general equivalent a «jo canto».", "a": ["cante"], "e": "Cante és la forma de la major part del valencià; canto, la del valencià septentrional."},
      {"q": "Escriu la forma en -ra equivalent a «que ell batés».", "a": ["batera"], "e": "Batés (en -s) = batera (en -ra): imperfet de subjuntiu de batre."}
    ]
  },
  {
    "id": "7a87b4ee-7d9b-5e13-b092-c95190d62c81", "type": "c1_mor_verbs_construccions", "sort_order": 15,
    "title": "Construccions verbals: impersonals i pronominals", "name": "Haver-hi, fer, passiva pronominal i concordança; transitius, inacusatius i verbs pronominals amb canvi de règim",
    "content": "Usos verbals en construccions transitives i intransitives, personals i impersonals (haver-hi, fer i verbs meteorològics, passiva perifràstica i passiva pronominal, concordança del verb amb el subjecte), i pronominals i no pronominals (oblidar / oblidar-se de, recordar / recordar-se de, anar-se'n, pujar-se'n, eixir-se'n, trobar-s'hi) (3.2.2).", "icon": "🔀", "color": "#F8BBD0",
    "exercises": [
      {"q": "Quina és l'opció més adequada en registre formal?", "o": ["Ahir hi havia molts espectadors.", "Ahir hi havien molts espectadors.", "Ahir havia molts espectadors."], "e": "Amb haver-hi, el SN es comporta com un complement directe; en registre formal es preferix la manca de concordança."},
      {"q": "Segons la GNV, què cal dir de «A ma casa hi han més cadires»?", "o": ["És acceptable, però en registre formal és més adequat hi ha.", "És incorrecta en qualsevol registre.", "És la forma preferida en el registre formal."], "e": "S'accepta la concordança i la manca de concordança, però la tradicional (hi ha) és més adequada en registres formals (GNV 32.2.2)."},
      {"q": "En «Hi ha tres sol·licituds», quina funció té «tres sol·licituds» segons la GNV?", "o": ["Complement directe d'un verb impersonal.", "Subjecte del verb haver-hi.", "Complement de règim."], "e": "Haver-hi és impersonal; el SN es comporta com un CD, i per això tradicionalment el verb no concorda."},
      {"q": "«L'any que ve ___ eleccions municipals.» (registre formal)", "o": ["hi haurà", "hi hauran", "haurà"], "e": "Haver-hi, impersonal: hi haurà, sense concordança en registre formal i amb el pronom hi lexicalitzat."},
      {"q": "Quina d'estes oracions és impersonal (no té subjecte)?", "o": ["Ha pedregat tota la nit.", "Ha arribat tard a la reunió.", "Han eixit de matí."], "e": "Els verbs meteorològics no tenen subjecte; en les altres el subjecte és el·líptic (GNV 8.5)."},
      {"q": "«___ molt de fred este hivern.» (temps atmosfèric)", "o": ["Fa", "Està", "És"], "e": "El temps atmosfèric s'expressa amb fer impersonal: fa fred, fa calor."},
      {"q": "«___ tres anys que viu a Elx.»", "o": ["Fa", "Fan", "Són"], "e": "Fer temporal és impersonal i no concorda amb el complement: fa tres anys."},
      {"q": "Per què «Plou» no porta cap pronom subjecte, a diferència del francés «Il pleut»?", "o": ["Perquè és impersonal i el valencià no ocupa la posició de subjecte buida amb cap pronom.", "Perquè el subjecte és el·líptic i es recupera pel context.", "Perquè ploure és un verb pronominal."], "e": "En les llengües que admeten l'elisió del subjecte, la posició de subjecte dels impersonals queda buida (GNV 8.5)."},
      {"q": "«Enguany ___ molts edificis pertot arreu.»", "o": ["s'han construït", "s'ha construït", "se n'ha construït"], "e": "Passiva pronominal: el SN (molts edificis) és el subjecte i el verb hi concorda."},
      {"q": "Quina opció és correcta en registre formal?", "o": ["En esta immobiliària es lloguen pisos.", "En esta immobiliària es lloga pisos.", "En esta immobiliària se lloga pisos."], "e": "En la passiva pronominal el verb concorda amb el SN, que n'és el subjecte: es lloguen pisos."},
      {"q": "Quina passiva perifràstica resulta natural segons la GNV?", "o": ["El gratacel serà construït per una empresa valenciana.", "El nou museu és construït per una empresa valenciana.", "El nou museu era construït per una empresa valenciana."], "e": "La passiva amb ser + participi té fortes restriccions en present i en imperfet."},
      {"q": "Quina d'estes oracions NO admet la conversió en passiva?", "o": ["Vicenta va tindre un xiquet.", "Els ponents van presentar el dictamen.", "L'empresa va construir el pont."], "e": "Els verbs estatius sense agent (tindre, saber, patir, els de mesura) no admeten la passiva."},
      {"q": "Quina d'estes formes NO és una alternativa correcta a «El dictamen va ser presentat ahir»?", "o": ["Ahir es van presentar el dictamen.", "Ahir es va presentar el dictamen.", "Ahir van presentar el dictamen."], "e": "En la passiva pronominal el verb concorda amb el subjecte singular (el dictamen): es va presentar."},
      {"q": "Quin recurs propi de la llengua general recomana la GNV per a convertir el CD en tema sense usar la passiva?", "o": ["La dislocació: El dictamen, el van presentar ahir els ponents.", "La passiva: El dictamen va ser presentat pels ponents.", "Hom: Hom va presentar el dictamen."], "e": "La dislocació del complement directe és el recurs normal per a donar-li el valor de tema informatiu (GNV 32.2.3)."},
      {"q": "En «La xiqueta ja no menja», com s'usa el verb «menjar»?", "o": ["Com a transitiu absolut, sense CD explícit.", "Com a verb impersonal.", "Com a verb pronominal."], "e": "Molts transitius poden usar-se sense CD quan es pressuposa un complement genèric (GNV 32.2.2)."},
      {"q": "En «Va viure una vida molt intensa», què és «una vida molt intensa»?", "o": ["Un acusatiu intern d'un verb intransitiu.", "Un complement circumstancial de temps.", "El subjecte."], "e": "Alguns intransitius (viure, plorar) admeten un CD íntimament relacionat amb el seu significat."},
      {"q": "En «Ha pesat quatre quilos», què expressa el complement?", "o": ["Una quantitat: és un CD de mesura.", "Un complement de règim.", "Un subjecte posposat."], "e": "Pesar, costar, valer, mesurar o durar seleccionen un complement que designa una quantitat."},
      {"q": "Quin d'estos verbs és inacusatiu?", "o": ["arribar", "treballar", "riure"], "e": "Arribar, eixir, nàixer, morir, caldre o ocórrer tenen un subjecte que es comporta com un CD: es posposa i es pronominalitza amb en."},
      {"q": "«En esta sala ___ dos cadires.» (faltar, present)", "o": ["falten", "falta", "hi falta"], "e": "Faltar és inacusatiu: el SN posposat és el subjecte i el verb hi concorda."},
      {"q": "«A l'assemblea ___ coses molt estranyes.» (ocórrer, perfet)", "o": ["han ocorregut", "ha ocorregut", "hi ha ocorregut"], "e": "Ocórrer és inacusatiu: concorda amb el subjecte posposat (coses)."},
      {"q": "Quina concordança afavorix la GNV en «La mitat dels alumnes ___»?", "o": ["ha protestat (concordança formal)", "han protestat (concordança pel sentit)", "és protestada"], "e": "Amb col·lectius numerals seguits de de + plural es tendix a la concordança formal (GNV 8.5.2)."},
      {"q": "«Els estudiants som molt responsables.» És correcta esta concordança?", "o": ["Sí: la concordança pel sentit permet incloure el parlant.", "No: ha de ser són.", "No: ha de ser sou."], "e": "Amb un subjecte plural, el verb pot concordar en 1a o 2a persona si inclou el parlant o l'oient (GNV 8.5.2)."},
      {"q": "«Cap de vosaltres no ___ a l'excursió.» Quina afirmació és correcta?", "o": ["S'accepta tant anirà com anireu.", "Només és correcte anirà.", "Només és correcte anireu."], "e": "Amb subjectes partitius, el verb pot concordar amb el quantificador o amb el pronom (GNV 8.5.2)."},
      {"q": "«Aquella multitud ___ treballadors del port.»", "o": ["són", "és", "està"], "e": "En una oració atributiva amb un col·lectiu i un nom plural es fa la concordança pel sentit."},
      {"q": "Quina oració és correcta?", "o": ["No t'oblides de la cita.", "No t'oblides la cita.", "No oblides de la cita."], "e": "Oblidar porta CD (oblidar la cita); oblidar-se, complement de règim amb de (oblidar-se de la cita)."},
      {"q": "Quin ús de «recordar» és correcte?", "o": ["Em vaig recordar del que t'havia promés.", "Em vaig recordar el que t'havia promés.", "Vaig recordar-me el que t'havia promés."], "e": "Recordar-se selecciona un complement de règim amb de; sense pronom, recordar és transitiu."},
      {"q": "Quina diferència hi ha entre «La xiqueta ha pujat a casa» i «La xiqueta se n'ha pujat a casa»?", "o": ["Pujar-se'n indica desplaçament des del lloc on s'estava (anar-se'n amunt).", "Cap: el pronom és un castellanisme.", "Pujar-se'n vol dir 'augmentar de preu'."], "e": "En anar-se'n, eixir-se'n, pujar-se'n o vindre-se'n, en lexicalitzat expressa desplaçament des d'un lloc."},
      {"q": "«Ja és tard: ___.» (deixe el lloc on soc)", "o": ["me'n vaig", "em vaig", "vaig"], "e": "Anar-se'n expressa l'abandonament d'un lloc; anar, sense pronom, requerix una destinació."},
      {"q": "«Abaixa el foc, que la llet bull i ___!» (vessar)", "o": ["se n'ix", "s'ix", "ix-se'n"], "e": "Eixir-se'n un líquid o un recipient significa 'vessar'."},
      {"q": "«Amb el vestit nou no m'hi trobe.» Què vol dir?", "o": ["Que no em sent còmode amb el vestit.", "Que he perdut el vestit.", "Que el vestit no és meu."], "e": "Trobar-s'hi, amb hi lexicalitzat, vol dir 'sentir-se bé, a gust' (GNV 23.4.2)."},
      {"q": "«No s'hi val!», dit en un joc, vol dir...", "o": ["que allò no està permés, no és lícit.", "que una cosa no té valor econòmic.", "que algú no se sap valdre."], "e": "Valer-s'hi, en frases fetes com no s'hi val, té hi lexicalitzat."},
      {"q": "«S'ha decidit ___ el model més econòmic.»", "o": ["pel", "en el", "al"], "e": "Decidir-se per una opció (complement de règim amb per), enfront de decidir alguna cosa."},
      {"q": "«No m'he atrevit ___ dir-li-ho.»", "o": ["a", "de", "en"], "e": "Atrevir-se selecciona un complement de règim amb a."},
      {"q": "«Es desviu per tots.» Què significa «desviure's per»?", "o": ["Dedicar-se amb molt d'interés a algú o a alguna cosa.", "Deixar de viure.", "Viure lluny d'algú."], "e": "Desviure's per és un verb pronominal que selecciona un complement de règim amb per (GNV 32.4)."},
      {"q": "Quin d'estos verbs pronominals funciona com a quasicopulatiu de canvi d'estat?", "o": ["fer-se (S'ha fet roig.)", "pentinar-se", "anar-se'n"], "e": "Fer-se, tornar-se o posar-se poden ser quasicopulatius amb sentit de canvi d'estat (GNV 33.2.1)."},
      {"q": "En «Es pentinen l'una a l'altra», quin valor té «es»?", "o": ["Recíproc", "Impersonal", "Passiu"], "e": "Els reflexius plurals tenen interpretació recíproca quan l'acció de cadascú recau sobre l'altre."},
      {"q": "Escriu la forma més adequada en registre formal: «En aquella època ___ pocs metges al poble.» (haver-hi, imperfet)", "a": ["hi havia"], "e": "En registre formal, haver-hi sense concordança: hi havia."},
      {"q": "Escriu en passiva pronominal: «En esta tenda ___ llibres de segona mà.» (vendre, present)", "a": ["es venen"], "e": "El SN plural és el subjecte de la passiva pronominal: es venen."},
      {"q": "Escriu la preposició: «Lluís es va oblidar ___ la cita amb nosaltres.»", "a": ["de"], "e": "Oblidar-se de: complement de règim (GNV 8.5.1)."},
      {"q": "Escriu els pronoms: «Havia d'arreplegar el xiquet, però no ___ vaig recordar.»", "a": ["me'n"], "e": "Recordar-se de + en (complement de règim): no me'n vaig recordar."},
      {"q": "Escriu els pronoms: «Sempre parla a la babalà i després ___ penedix.»", "a": ["se'n"], "e": "Penedir-se de: el complement de règim es pronominalitza amb en."},
      {"q": "Completa la dislocació amb el pronom de represa: «El dictamen, ___ van presentar ahir els ponents.»", "a": ["el"], "e": "La dislocació del CD exigix un pronom de represa: El dictamen, el van presentar..."},
      {"q": "Escriu el verb concordat: «Ja ___ uns parents meus.» (arribar, perfet)", "a": ["han arribat"], "e": "Arribar és inacusatiu: el subjecte posposat concorda amb el verb."},
      {"q": "Escriu la preposició: «Al final hem optat ___ anar a la platja.»", "a": ["per"], "e": "Optar per: complement de règim amb per (GNV 32.4)."}
    ]
  },
  {
    "id": "85cacabb-fb0b-5aaf-90d4-4e6da3fbe8e1", "type": "c1_mor_perifrasis", "sort_order": 16,
    "title": "Perífrasis d'obligació, probabilitat i imminència", "name": "Haver de, deure, caldre, tindre de i estar a punt de, i alternatives a tindre que, hi ha que i anar a",
    "content": "Perífrasis verbals i altres construccions d'obligació (haver de + infinitiu, deure + infinitiu, caldre + infinitiu, caldre que + subjuntiu, tindre de + infinitiu), perífrasi de probabilitat (deure + infinitiu) i perífrasi d'imminència (estar a punt de + infinitiu), amb les alternatives a les construccions calcades tindre que, hi ha que, anar a + infinitiu amb valor de futur i portar + gerundi (3.2.2).", "icon": "🧭", "color": "#C5CAE9",
    "exercises": [
      {"q": "Quina és la forma correcta de «Tinc que anar al metge»?", "o": ["He d'anar al metge.", "Tinc de que anar al metge.", "Hi ha que anar al metge."], "e": "Tindre que no és acceptable; la perífrasi habitual és haver de (tindre de és correcta, però poc usada)."},
      {"q": "Segons la GNV, com cal valorar «tindre de + infinitiu»?", "o": ["Correcta, però poc usada.", "Incorrecta, com tindre que.", "La forma preferida en registre formal."], "e": "No són acceptables hi ha que ni tindre que, però sí tindre de, tot i que és poc usada (GNV 31.3.d)."},
      {"q": "Quina és l'alternativa correcta a «Hi ha que revisar el pressupost»?", "o": ["Cal revisar el pressupost.", "Hi ha de revisar el pressupost.", "Té que revisar-se el pressupost."], "e": "Hi ha que és un calc no acceptable; l'obligació impersonal s'expressa amb caldre o ser necessari."},
      {"q": "En valor modal, quina forma de primera persona d'haver de és correcta?", "o": ["Totes dues: he de dir-te una cosa / haig de dir-te una cosa.", "Només he de.", "Només haig de."], "e": "Haver admet la forma palatalitzada haig, junt amb he, quan funciona com a verb modal (GNV 30.2.2.c)."},
      {"q": "Quina oració és INCORRECTA?", "o": ["Haig cantat tota la nit.", "Haig de cantar tota la nit.", "He cantat tota la nit."], "e": "Haig només s'admet en la perífrasi modal; com a auxiliar del perfet és sempre he."},
      {"q": "Quina oració expressa una obligació amb clara connotació moral?", "o": ["Els fills deuen obeir els pares.", "Deuen ser les cinc.", "Ja deuen haver arribat."], "e": "Deure + infinitiu pot tindre valor d'obligació, sobretot amb connotació moral (GNV 31.3.b)."},
      {"q": "Quina oració és correcta?", "o": ["Deuen ser les cinc.", "Deuen de ser les cinc.", "Tenen que ser les cinc."], "e": "La perífrasi amb deure no porta mai la preposició de entre l'auxiliar i l'infinitiu."},
      {"q": "«No contesten al telèfon: ___ la música molt forta.» (suposició)", "o": ["deuen tindre", "deuen de tindre", "tenen que tindre"], "e": "Deure + infinitiu expressa una deducció no confirmada; sense de."},
      {"q": "Quina oració expressa una suposició sobre el passat?", "o": ["Ja deuen haver arribat.", "Ja han d'arribar.", "Ja van a arribar."], "e": "Deure + infinitiu compost (haver arribat) situa la suposició en el passat."},
      {"q": "Amb valor de probabilitat, quina forma de passat de «deure» és correcta?", "o": ["Li ho degué dir ell.", "Li ho va deure dir ell.", "Li ho va deure de dir ell."], "e": "Deure és l'únic verb que admet el passat simple però no el perifràstic (GNV 28.4.1)."},
      {"q": "Segons la GNV, quin és el recurs més habitual en registre formal per a expressar probabilitat?", "o": ["La perífrasi deure + infinitiu (Deuen estar dormint).", "El futur (Estaran dormint).", "La perífrasi anar a + infinitiu."], "e": "També s'usa el futur de probabilitat, però la perífrasi amb deure és més habitual en els registres formals."},
      {"q": "«Han de tindre la música molt forta perquè no contesten.» Quin valor té ací «haver de»?", "o": ["De deducció o probabilitat.", "D'obligació.", "D'imminència."], "e": "A més d'obligació, haver de pot assumir valor de probabilitat o de futur emfàtic (GNV 31.3.d)."},
      {"q": "«Entra la roba, que ha de ploure.» Quin valor té «ha de ploure»?", "o": ["Futur emfàtic.", "Obligació moral.", "Passat recent."], "e": "La GNV recull este valor de futur emfàtic per a haver de."},
      {"q": "Quina construcció d'obligació és impersonal?", "o": ["Cal que ens comuniqueu el resultat.", "Heu de comunicar-nos el resultat.", "Deveu comunicar-nos el resultat."], "e": "Caldre s'usa en construccions impersonals, amb infinitiu o amb que + subjuntiu."},
      {"q": "Quina construcció amb «caldre» és correcta?", "o": ["Cal presentar la sol·licitud abans de dilluns.", "Cal de presentar la sol·licitud abans de dilluns.", "Cal que presentar la sol·licitud abans de dilluns."], "e": "Caldre + infinitiu, sense preposició; o bé caldre que + subjuntiu."},
      {"q": "«Cal que ___ a la reunió.» (vindre, vosaltres)", "o": ["vingueu", "veniu", "vindreu"], "e": "Caldre que exigix subjuntiu: vingueu."},
      {"q": "«Calia que ___ abans.» (avisar, tu)", "o": ["m'avisares", "m'avises", "m'avisaves"], "e": "Amb caldre en passat, la subordinada va en imperfet de subjuntiu."},
      {"q": "«És necessari que ___ a la reunió de la cooperativa.» (assistir, tu)", "o": ["assistisques", "assistixes", "assistiràs"], "e": "Ser necessari que, com caldre que, exigix subjuntiu."},
      {"q": "Quina d'estes construccions d'obligació NO és acceptable segons la GNV?", "o": ["hi ha que + infinitiu", "tindre de + infinitiu", "ser necessari que + subjuntiu"], "e": "Hi ha que i tindre que no són acceptables; tindre de sí, tot i que és poc usada."},
      {"q": "«___ pensar en altres alternatives.» (consell suau, nosaltres)", "o": ["Hauríem de", "Tindríem que", "Deuríem de"], "e": "El condicional d'haver de atenua l'obligació; tindre que i deure de no són acceptables."},
      {"q": "Quina oració expressa una acció imminent d'acord amb l'ús recomanat?", "o": ["Calleu, que està a punt de començar l'obra.", "Calleu, que va a començar l'obra.", "Calleu, que anirà a començar l'obra."], "e": "Anar a + infinitiu s'usa poc amb valor d'imminència; s'usa estar a punt de (GNV 31.4.a)."},
      {"q": "Quina és la versió més genuïna de «La comissió es va a reunir dilluns»?", "o": ["La comissió es reunirà dilluns.", "La comissió es va reunir dilluns.", "La comissió està per reunir-se dilluns."], "e": "Anar a + infinitiu no ha desenvolupat el valor de futur: s'usa el futur."},
      {"q": "Per què s'evita en valencià «Ara vos vaig a dir el que va passar»?", "o": ["Perquè es pot confondre amb el passat perifràstic i no té valor de futur: Ara vos diré...", "Perquè vos és incorrecte.", "Perquè anar mai no pot anar seguit de a."], "e": "Vaig + infinitiu és el passat perifràstic; per al futur s'usa el futur simple."},
      {"q": "Quina expressió és la recomanada per a introduir una explicació?", "o": ["A veure, parla un poc més clar.", "Anem a veure, parla un poc més clar.", "Anem a vore, parla un poc més clar."], "e": "La GNV recomana a veure en lloc de anem a veure."},
      {"q": "En quin cas és correcte «anar a + infinitiu»?", "o": ["Han tocat a la porta i vaig a veure qui és.", "Demà vaig a comprar-me un cotxe nou.", "Esta nit va a ploure."], "e": "És correcte quan anar és un verb de moviment; no com a futur."},
      {"q": "«Anàvem a eixir de casa quan hem sentit el telèfon.» És correcta?", "o": ["Sí: en imperfet, anar a expressa una acció que no s'arriba a realitzar.", "No: cal dir eixírem.", "No: anar a mai no és correcte."], "e": "La perífrasi és habitual en imperfet d'indicatiu o de subjuntiu amb valor de conat (GNV 31.4.a)."},
      {"q": "«Jo estic per dir-li-ho i que faça el que vullga.» Quin valor té «estar per»?", "o": ["Intenció d'una acció imminent.", "Obligació.", "Probabilitat."], "e": "Estar per + infinitiu expressa que algú té la intenció de fer una cosa o que està pendent de produir-se."},
      {"q": "«La sorpresa més gran està per arribar.» Què vol dir?", "o": ["Que encara no s'ha produït, però s'ha de produir.", "Que ja ha arribat.", "Que no arribarà mai."], "e": "Estar per + infinitiu també expressa que una cosa està pendent de produir-se (GVB 40.2.8)."},
      {"q": "«Es van alterar tant que pareixia que ___ pegar-se.»", "o": ["estaven a punt de", "anaven de", "estaven per a"], "e": "Estar a punt de + infinitiu expressa imminència (GVB 40.2.3)."},
      {"q": "«—Què fas? —___» (resposta més tradicional, sense èmfasi en la durada)", "o": ["Prepare el sopar.", "Estic preparant el sopar.", "Vaig preparant el sopar."], "e": "Convé evitar estar + gerundi quan no es vol remarcar la durada o la repetició (GNV 31.4.b)."},
      {"q": "Quina és l'alternativa genuïna a «Porta tres anys estudiant alemany»?", "o": ["Fa tres anys que estudia alemany.", "Ve estudiant alemany tres anys.", "Està tres anys estudiant alemany."], "e": "La GNV recomana evitar portar o vindre en perífrasis de gerundi amb valor duratiu."},
      {"q": "Quina oració usa correctament «acabar de»?", "o": ["El nou sistema no m'acaba de convéncer.", "Acaba de convéncer-me el sistema que no.", "El nou sistema m'acaba de no convéncer."], "e": "En contextos negatius, acabar de + infinitiu atenua la negació (GVB 40.2.1)."},
      {"q": "Quina prova mostra que «puc dir» és una perífrasi?", "o": ["El pronom pot anteposar-se a tot el conjunt: t'ho puc dir.", "Es pot dir Ho puc.", "Es pot dir Puc que em digues."], "e": "En una perífrasi els pronoms de l'infinitiu poden anar davant de l'auxiliar; no es pot substituir l'infinitiu per ho (GNV 31.2)."},
      {"q": "Escriu l'auxiliar en present (jo) d'«haver de»: «___ d'anar al metge demà.»", "a": ["haig", "he"], "e": "He de o haig de: totes dues formes s'admeten en la perífrasi d'obligació."},
      {"q": "Corregix: «Teniu que estudiar més.» → «___ d'estudiar més.»", "a": ["heu"], "e": "Haver de: heu d'estudiar. Tindre que no és acceptable."},
      {"q": "Escriu el verb: «No hi ha llum: ___ estar dormint.» (deure, ell, probabilitat)", "a": ["deu"], "e": "Deure + infinitiu, sense de: deu estar dormint."},
      {"q": "Escriu l'imperfet de «deure»: «Quan la vaig conéixer, ___ tindre uns vint anys.»", "a": ["devia"], "e": "Imperfet de deure: devia, devies, devia... (probabilitat en el passat)."},
      {"q": "Escriu el futur de «caldre»: «___ que ens comuniqueu el resultat tan prompte com siga possible.»", "a": ["caldrà"], "e": "Caldre que + subjuntiu, ací en futur: caldrà."},
      {"q": "Escriu el verb: «Calia que m'ho ___ abans.» (dir, tu)", "a": ["digueres"], "e": "Caldre en passat + imperfet de subjuntiu: digueres."},
      {"q": "Escriu la preposició: «Calleu, que està a punt ___ començar.»", "a": ["de"], "e": "Estar a punt de + infinitiu."},
      {"q": "Escriu el futur en lloc del calc «va a ploure»: «Esta nit ___, segons la previsió.» (ploure)", "a": ["plourà"], "e": "Anar a + infinitiu no té valor de futur: plourà."},
      {"q": "Escriu la preposició: «Jo estic ___ dir-li-ho i que faça el que vullga.»", "a": ["per"], "e": "Estar per + infinitiu: intenció d'una acció imminent."},
      {"q": "Escriu el verb: «No ___ que vingues, si no vols.» (caldre, present)", "a": ["cal"], "e": "No cal que + subjuntiu."}
    ]
  },
  {
    "id": "b09839a0-ecdf-5052-ac1b-75149d6df246", "type": "c1_mor_ser_estar", "sort_order": 17,
    "title": "Ser i estar: atribució, localització i passiva", "name": "Propietats i estats, subjectes animats i inanimats, localització duradora, haver-hi presentacional i passiva",
    "content": "Usos de ser i estar segons la normativa: selecció del verb en les construccions atributives segons el tipus d'atribut (propietat o estat transitori) i de subjecte (animat o inanimat), els usos que admeten totes dues opcions (la llet és/està calenta, és/està casat), la incompatibilitat d'estar amb atributs nominals, els usos locatius en contextos duratius i no duratius, les construccions presentacionals amb haver-hi, la passiva perifràstica i la pronominalització de l'atribut i del predicatiu (3.2.2).", "icon": "⚖️", "color": "#C8E6C9",
    "exercises": [
      {"q": "«Robert ___ un bon home.»", "o": ["és", "està", "hi ha"], "e": "Amb un atribut nominal (un bon home) només és possible ser: estar és incompatible amb els atributs constituïts per un sintagma nominal."},
      {"q": "Quina frase és incorrecta?", "o": ["El nou director està un home molt prudent.", "El nou director és un home molt prudent.", "El nou director està molt preocupat."], "e": "Estar no admet un atribut nominal (*està un home*); sí que admet adjectius d'estat (*està preocupat*)."},
      {"q": "«Maria ___ de Castelló, però viu a Alcoi.» (origen)", "o": ["és", "està", "estava"], "e": "L'origen és una propietat: amb atributs que indiquen propietats s'usa ser, siga quina siga la forma de l'atribut."},
      {"q": "«Este café ___ sense cafeïna.»", "o": ["és", "està", "té"], "e": "És una propietat del café, expressada amb un sintagma preposicional: ser (és sense cafeïna)."},
      {"q": "«Els xiquets ___ en perill si no tanquem la piscina.»", "o": ["estan", "són", "hi són"], "e": "Subjecte animat + estat transitori expressat amb un sintagma preposicional: l'ús general és estar."},
      {"q": "«Carme ja ___ bé: demà torna a treballar.»", "o": ["està", "és", "fa"], "e": "Subjecte animat + estat transitori expressat amb un adverbi: estar (està bé)."},
      {"q": "«No feu soroll, que la mare ___ gitada.»", "o": ["està", "és", "ha"], "e": "Subjecte animat + participi que indica un estat: estar (està gitada)."},
      {"q": "Sobre «La llet és calenta» i «La llet està calenta», quina afirmació és correcta segons la GNV?", "o": ["Totes dues són correctes: ser és l'ús més tradicional i estar s'ha estés.", "Només és correcta la segona, perquè es tracta d'un estat.", "Només és correcta la primera, perquè el subjecte és inanimat."], "e": "Amb subjecte inanimat i atribut adjectival d'estat, l'ús tradicional i genuí és ser, però estar té cada vegada més difusió: les dos opcions són vàlides."},
      {"q": "«El camp ___ ple de brossa.» Quines opcions admet la GNV?", "o": ["és o està", "només està", "només és"], "e": "Subjecte inanimat + adjectiu d'estat: ser (ús tradicional) o estar (ús estés). Totes dues són correctes."},
      {"q": "Sobre «Pere és casat» i «Pere està casat», quina afirmació és correcta?", "o": ["Totes dues són acceptables: l'estat civil s'ha vist tradicionalment com una propietat, però hui també es concep com a transitori.", "Només és correcta la segona, perquè ser no pot expressar l'estat civil.", "Només és correcta la primera; estar casat és un castellanisme."], "e": "La GNV recull l'ús tradicional amb ser (és casat, és viuda) i la tendència actual a usar estar (està casat)."},
      {"q": "Segons la GNV, amb subjecte inanimat i atribut format per un participi («La casa ___ tancada des de l'estiu»), quin és l'ús més estés?", "o": ["estar", "ser", "haver-hi"], "e": "Amb participis, sintagmes preposicionals i adverbis referits a subjectes inanimats, l'ús més estés és estar: la casa està tancada."},
      {"q": "«Quan he arribat a casa, el teu fill ___ al carrer.» (registre formal; simple localització)", "o": ["era", "estava", "hi havia"], "e": "Si la localització no destaca la durada, el registre formal tria ser; l'ús d'estar en estos contextos és una tendència col·loquial que convé evitar."},
      {"q": "«El teu fill ___ tot el dia al carrer.» (permanència)", "o": ["està", "hi ha", "fa"], "e": "Quan la localització destaca la durada o permanència (tot el dia), es tria estar."},
      {"q": "«El llapis que busques ___ al calaix.» (registre formal; simple localització)", "o": ["és", "hi ha", "fa"], "e": "Localització no durativa d'un objecte: ser. Ex.: El llapis que busques és al calaix."},
      {"q": "«El llapis ___ sempre al calaix: no l'ha mogut ningú.»", "o": ["ha estat", "ha hagut", "ha fet"], "e": "Amb un context duratiu (sempre), la localització s'expressa amb estar: ha estat sempre al calaix."},
      {"q": "Quina frase segueix l'ús dels registres formals?", "o": ["Quan va sonar el telèfon, jo era a la cuina.", "Quan va sonar el telèfon, jo estava a la cuina.", "Quan va sonar el telèfon, jo hi havia a la cuina."], "e": "Localització puntual (no durativa): en els registres formals, ser. La GNV recomana evitar estar en els contextos propis de ser."},
      {"q": "«Fora ___ l'home que vingué ahir.» (registre formal)", "o": ["hi ha", "està", "fa"], "e": "Les construccions presentacionals (que introduïxen un element en el discurs) usen haver-hi; l'ús d'estar convé evitar-lo en registres formals."},
      {"q": "«Al baül ___ una de les figures més boniques que tinc.» (registre formal)", "o": ["hi ha", "està", "hi està"], "e": "Construcció presentacional: haver-hi. *Al baül està una de les figures* és un ús que convé evitar."},
      {"q": "Quina frase és adequada en un registre formal?", "o": ["A la porta hi ha uns senyors que pregunten per tu.", "A la porta estan uns senyors que pregunten per tu."], "e": "Per a presentar un element nou en el discurs s'usa haver-hi, no estar."},
      {"q": "Completa el refrany: «On ___ el cos, ___ la mort.»", "o": ["hi ha / hi ha", "està / està", "és / és"], "e": "El refrany conserva l'ús tradicional d'haver-hi en les construccions presentacionals."},
      {"q": "«El dictamen ___ presentat ahir pels ponents.»", "o": ["va ser", "va estar", "va haver"], "e": "La passiva perifràstica es forma amb ser + participi, que concorda amb el subjecte."},
      {"q": "Quina oració passiva resulta natural segons la GNV?", "o": ["El gratacel serà construït per una empresa valenciana.", "El nou museu és construït per una empresa valenciana.", "El nou museu era construït per una empresa valenciana."], "e": "La passiva perifràstica és normal en futur o passat perfectiu, però resulta anòmala en present i en imperfet."},
      {"q": "Quina és l'alternativa més habitual en la llengua general a «El dictamen va ser presentat ahir»?", "o": ["Ahir es va presentar el dictamen.", "Ahir va estar presentat el dictamen.", "Ahir el dictamen estigué presentat."], "e": "La passiva perifràstica és pròpia de la llengua escrita; en la llengua general es preferix la passiva pronominal (es va presentar) o la tercera persona del plural."},
      {"q": "Quina oració passiva NO és possible?", "o": ["Un xiquet va ser tingut per Vicenta.", "La llei va ser aprovada pel Parlament.", "El pont serà inaugurat per l'alcaldessa."], "e": "Els verbs estatius sense agent (tindre, saber, patir) no admeten la passiva: *Un xiquet va ser tingut per Vicenta."},
      {"q": "«—La teua germana, és més gran que tu? —Sí, ___ és.»", "o": ["ho", "la", "hi"], "e": "L'atribut de ser, estar, paréixer i semblar es pronominalitza amb el pronom neutre ho."},
      {"q": "«Sa mare és magribina, però ell no s'___ sent.»", "o": ["hi", "ho", "en"], "e": "Amb els verbs quasicopulatius que no són ser, estar, paréixer o semblar (com sentir-se), l'atribut es pronominalitza amb hi."},
      {"q": "«—Han arribat cansats, els teus pares? —Sí que ___ han arribat.»", "o": ["hi", "ho", "els"], "e": "El complement predicatiu es pronominalitza amb hi: hi han arribat (cansats)."},
      {"q": "«Jo ___ per dir-li-ho i que faça el que vullga.» (intenció)", "o": ["estic", "soc", "he"], "e": "La perífrasi estar per + infinitiu expressa intenció o una acció pendent."},
      {"q": "«La sorpresa més gran ___ per arribar.»", "o": ["està", "és", "ha"], "e": "Estar per + infinitiu: una cosa pendent de produir-se (la sorpresa està per arribar)."},
      {"q": "«L'expedició ha arribat ___ a València.»", "o": ["contenta", "content", "contents"], "e": "El complement predicatiu concorda amb el sintagma nominal sobre el qual predica: l'expedició → contenta."},
      {"q": "«Miquel diu que ha vist tota la gent ___.»", "o": ["dreta", "dret", "drets"], "e": "Predicatiu referit al complement directe (tota la gent): concorda en femení singular."},
      {"q": "«Aquella escultura ___ de pedra, però en realitat és de fusta.»", "o": ["pareix", "està", "hi ha"], "e": "Paréixer és quasicopulatiu (aporta un matís modal d'aparença) i admet atributs preposicionals: pareix de pedra."},
      {"q": "«Quan li ho he dit, s'ha ___ roig com un tomaca.»", "o": ["fet", "estat", "sigut"], "e": "Fer-se és un verb quasicopulatiu de canvi d'estat: s'ha fet roig. Ser i estar no són pronominals."},
      {"q": "Quina frase usa el verb adequat en un registre formal?", "o": ["Els documents que necessites són al calaix de dalt.", "Fora està l'home que vingué ahir.", "Robert està un bon home."], "e": "Localització no durativa amb ser (correcte); la presentacional demana haver-hi i un atribut nominal demana ser."},
      {"q": "Quina d'estes frases és incorrecta?", "o": ["La reunió està un èxit.", "La reunió és un èxit.", "La reunió és a la sala de juntes."], "e": "Un èxit és un sintagma nominal: amb atribut nominal només es pot usar ser."},
      {"q": "Escriu el futur de ser: «Demà l'informe ___ presentat al ple.»", "a": ["serà"], "e": "Passiva perifràstica en futur: serà presentat."},
      {"q": "Escriu el passat perifràstic de ser: «Les propostes ___ aprovades per unanimitat.»", "a": ["van ser", "varen ser"], "e": "Passiva perifràstica: van ser aprovades; el participi concorda amb el subjecte."},
      {"q": "Escriu ser o estar (imperfet, registre formal): «Quan hem trucat, el director ja no ___ al despatx.»", "a": ["era"], "e": "Localització no durativa: en registre formal, ser (era al despatx)."},
      {"q": "Escriu ser o estar (present): «Fa dos hores que ___ en la biblioteca.» (ells)", "a": ["estan"], "e": "Context duratiu (fa dos hores que...): estar."},
      {"q": "Escriu el pronom: «—Estàs content? —Sí, ___ estic.»", "a": ["ho"], "e": "L'atribut d'estar es pronominalitza amb ho."},
      {"q": "Escriu el pronom: «Pareixen satisfets, però no ___ estan.»", "a": ["ho"], "e": "Atribut d'estar → ho: no ho estan."},
      {"q": "Escriu el pronom: «—Ha entrat de mestra, Carme? —No, no ___ ha entrat.»", "a": ["hi"], "e": "El predicatiu (de mestra) es pronominalitza amb hi."},
      {"q": "Escriu la forma femenina del predicatiu: «Sempre me l'he imaginada ___.» (alcalde)", "a": ["alcaldessa"], "e": "El predicatiu nominal concorda amb el complement directe (la): alcaldessa."},
      {"q": "Escriu el verb presentacional: «En la plaça ___ un mercat d'antiguitats cada diumenge.»", "a": ["hi ha"], "e": "Per a introduir un element nou en el discurs s'usa haver-hi, no estar."}
    ]
  },
  {
    "id": "a0a9222c-21e6-52eb-a0f2-05e544343958", "type": "c1_mor_formes_no_personals", "sort_order": 18,
    "title": "Formes no personals: infinitiu, gerundi i participi", "name": "Substantivació de l'infinitiu, participis irregulars i concordats, gerundi de posterioritat i gerundis irregulars",
    "content": "Ús adequat de les formes no personals del verb d'acord amb els usos del valencià: restricció de la substantivació de l'infinitiu i de l'infinitiu amb valor d'orde o de recapitulació; participis irregulars (admés, confós, detingut, distret, exclòs...); concordança del participi amb els pronoms acusatius de tercera persona (me les he acabades, la pregunta l'he compresa); ús incorrecte del gerundi de posterioritat i del gerundi adjectival, i formes irregulars del gerundi (bevent, traent/traient, estenent...) (3.2.2).", "icon": "🧬", "color": "#F8BBD0",
    "exercises": [
      {"q": "Quina frase s'ajusta a la llengua més general?", "o": ["Conduir de nit li fa por.", "El conduir de nit li fa por.", "Lo conduir de nit li fa por."], "e": "Convé evitar la substantivació de l'infinitiu amb article quan conserva complements verbals: n'hi ha prou amb l'infinitiu sol."},
      {"q": "«___ dir sempre la veritat li ha costat més d'un disgust.»", "o": ["El fet de", "El", "Lo"], "e": "Una alternativa a l'infinitiu amb article és el sintagma el fet de + infinitiu (o l'infinitiu sol)."},
      {"q": "Quina alternativa amb substantiu equival a «El conéixer bé l'anglés l'ha ajudat a trobar treball»?", "o": ["La bona coneixença de l'anglés l'ha ajudat a trobar treball.", "Lo conéixer bé l'anglés l'ha ajudat a trobar treball.", "El conéixer-lo bé, l'anglés, l'ha ajudat a trobar treball."], "e": "A més de l'infinitiu sol o el fet de, es pot recórrer a un substantiu: la bona coneixença de l'anglés."},
      {"q": "En quin cas l'infinitiu és un verdader substantiu (admet plural i modificadors nominals)?", "o": ["Hem fet tres sopars amb els amics de la colla.", "El viatjar sovint l'esgota.", "El cantar tota la nit l'ha deixat afònic."], "e": "Sopar, dinar, berenar o somriure són substantius procedents d'infinitius: admeten plural (sopars) i determinants."},
      {"q": "«En un ___ d'ulls va acabar el treball.» (locució)", "o": ["batre", "bateig", "batut"], "e": "Locució amb infinitiu substantivat: en un batre d'ulls (també en un tancar i obrir d'ulls)."},
      {"q": "Sobre el refrany «El saber no ocupa lloc», quina afirmació és correcta?", "o": ["És correcte: saber hi funciona com a substantiu.", "És incorrecte: cal dir «Saber no ocupa lloc».", "És incorrecte: cal dir «Lo saber no ocupa lloc»."], "e": "Hi ha infinitius substantivats en certs usos i locucions, com el saber; per això admeten l'article."},
      {"q": "Per a acabar un discurs, quina frase és adequada?", "o": ["Per a concloure, hem de dir que estem molt satisfets de la participació.", "Per a concloure, dir que estem molt satisfets de la participació.", "Per a concloure, decir que estem molt satisfets de la participació."], "e": "L'infinitiu com a verb principal amb valor de recapitulació és una innovació no recomanable: cal un verb conjugat (hem de dir, cal dir, direm)."},
      {"q": "Quina conclusió d'una presentació és adequada?", "o": ["Finalment, volem agrair-vos l'assistència.", "Finalment, agrair-vos l'assistència.", "Finalment, i per acabar, agrair-vos l'assistència."], "e": "No s'ha d'usar l'infinitiu tot sol com a verb principal: volem agrair-vos, cal agrair-vos..."},
      {"q": "En quin cas l'infinitiu amb valor d'orde és correcte?", "o": ["A dormir, que ja és tardíssim!", "No fumar en tot el recinte.", "Tancar bé la porta després d'eixir."], "e": "L'infinitiu pot fer d'orde precedit de la preposició a (A callar! A dormir!); tot sol, no: Es prohibix fumar, Tanqueu bé la porta."},
      {"q": "«La policia ha ___ els sospitosos.» (detindre)", "o": ["detingut", "detés", "detenit"], "e": "Els derivats de tindre fan el participi en -gut: detingut. La forma detés, per analogia amb entendre, no és acceptable."},
      {"q": "«L'empresa ha ___ els preus durant tot l'any.» (mantindre)", "o": ["mantingut", "mantés", "mantenit"], "e": "Mantindre → mantingut; mantés no és acceptable."},
      {"q": "«Estava tan ___ que no va sentir el timbre.» (distraure)", "o": ["distret", "distraït", "distragut"], "e": "Distraure fa el participi fort en -t, com traure (tret): distret, distreta."},
      {"q": "«Han quedat ___ de la llista els aspirants que no es van presentar.» (excloure)", "o": ["exclosos", "excloguts", "exclòsos"], "e": "Els verbs en -cloure fan el participi sigmàtic: exclòs, exclosa, exclosos, excloses (sense accent en el plural, que és pla)."},
      {"q": "«L'IVA ja està ___ en el preu.» (incloure)", "o": ["inclòs", "inclós", "incloït"], "e": "Incloure → inclòs, amb o oberta i accent obert."},
      {"q": "«El llibre està ___ en paper reciclat.» (imprimir)", "o": ["imprés", "imprimit", "imprès"], "e": "Imprimir té participi sigmàtic: imprés, impresa, amb accent tancat en valencià."},
      {"q": "«He ___ el formulari i l'he enviat.» (omplir)", "o": ["omplit", "omplert", "omplenat"], "e": "En valencià, omplir, complir, establir, oferir o sofrir fan el participi regular: omplit; les formes en -ert són d'altres parlars."},
      {"q": "«Ens han ___ un contracte indefinit.» (oferir)", "o": ["oferit", "ofert", "oferint"], "e": "Oferir té en valencià el participi feble regular: oferit."},
      {"q": "«El problema ja està ___.» (resoldre)", "o": ["resolt", "resolgut", "resolvit"], "e": "Els verbs acabats en -ldre fan el participi en -t: resolt, absolt, molt."},
      {"q": "«La gallina ja ha ___ els ous.» (pondre)", "o": ["post", "pongut", "ponit"], "e": "Pondre té un participi en -st: post, posta (com respondre: respost)."},
      {"q": "«Encara no m'ha ___ el correu.» (respondre)", "o": ["respost", "respongut", "responit"], "e": "Respondre → respost, participi en -st."},
      {"q": "Quins participis admet el verb riure?", "o": ["rist i rigut", "només rigut", "només rist"], "e": "Riure té un participi en -st (rist) i també admet la forma regular rigut."},
      {"q": "«—Queden mandonguilles? —No, me les he ___ al migdia.» (acabar, amb concordança)", "o": ["acabades", "acabat", "acabats"], "e": "El participi concorda amb el pronom acusatiu de tercera persona les (= les mandonguilles): acabades."},
      {"q": "«Les respostes, no les he ___ trobar.» (saber, amb concordança)", "o": ["sabudes", "sabut", "sapigudes"], "e": "Si el pronom s'anteposa al conjunt verbal, el participi concorda encara que el pronom siga complement de l'infinitiu: no les he sabudes trobar."},
      {"q": "«A les veïnes, els he ___ un pastís.» (portar)", "o": ["portat", "portades", "portats"], "e": "Els és ací complement indirecte (datiu): el participi només concorda amb els acusatius lo, la, los, les."},
      {"q": "«La fruita, l'ha ___ el meu germà.» (dur, amb concordança)", "o": ["duta", "dut", "duguda"], "e": "Dur té participi fort: dut, duta. Amb l'acusatiu femení la, concorda: l'ha duta."},
      {"q": "Quina frase és correcta?", "o": ["Va relliscar i es va trencar el braç.", "Va relliscar trencant-se el braç.", "Va relliscar, trencant-se el braç."], "e": "El gerundi indica simultaneïtat; no es pot usar per a una conseqüència posterior: cal coordinar (i es va trencar)."},
      {"q": "Com es corregix «L'autobús va bolcar, ferint deu passatgers»?", "o": ["L'autobús va bolcar i va ferir deu passatgers.", "L'autobús va bolcar, havent ferit deu passatgers.", "L'autobús, ferint deu passatgers, va bolcar."], "e": "Gerundi de posterioritat incorrecte: la conseqüència s'expressa amb una oració coordinada."},
      {"q": "Quina d'estes frases és correcta?", "o": ["El Govern ha aprovat un decret que regula els horaris comercials.", "El Govern ha aprovat un decret regulant els horaris comercials.", "El Govern ha aprovat un decret regulant-se els horaris comercials."], "e": "El gerundi no pot fer de modificador d'un nom amb valor de relativa especificativa: un decret que regula..."},
      {"q": "«L'administrador va enviar un escrit ___ els acords adoptats.»", "o": ["que resumia", "resumint", "resumit"], "e": "Amb valor adjectival cal una oració de relatiu: un escrit que resumia; *un escrit resumint* no és adequat."},
      {"q": "En quin cas és acceptable el gerundi al costat d'un substantiu?", "o": ["Les paraules del president encoratjant els jugadors foren molt efectives.", "Busquem un professor parlant anglés.", "Han aprovat una llei prohibint fumar en els parcs."], "e": "Amb certs substantius (de comunicació, percepció, deverbals) el gerundi pot tindre valor adverbial; com a relativa especificativa, no."},
      {"q": "Quina frase usa el gerundi amb el seu valor propi (simultaneïtat)?", "o": ["Preparant el sopar, em vaig recordar del que t'havia promés.", "Va obrir la porta, entrant després al pis.", "Es va casar l'any 2010, divorciant-se l'any 2015."], "e": "El gerundi és imperfectiu i expressa simultaneïtat amb la principal; les altres frases expressen fets posteriors."},
      {"q": "Quin és el gerundi de «beure»?", "o": ["bevent", "bebent", "beguent"], "e": "Beure fa bevent, amb v (com bevia, begut)."},
      {"q": "Quin és el gerundi de «traure»?", "o": ["traent (o traient)", "traguent", "trayent"], "e": "Traure admet traent i traient; les formes velaritzades del tipus traguent no són acceptables."},
      {"q": "Quin és el gerundi d'«estendre»?", "o": ["estenent", "estenguent", "estendent"], "e": "Estendre fa estenent, sense velaritzar, com prendre (prenent) o encendre (encenent)."},
      {"q": "Quin és el gerundi de «caure»?", "o": ["caient (o caent)", "caiguent", "cayent"], "e": "La GNV admet caient i caent; les formes velaritzades com caiguent no són acceptables."},
      {"q": "Quin és el gerundi de «vindre»?", "o": ["venint", "vinguent", "vindrent"], "e": "Vindre fa venint, igual que tindre fa tenint; cap gerundi no té velar."},
      {"q": "Escriu la forma composta del gerundi: «___ analitzat molt el tema, no hem arribat a cap solució.» (haver)", "a": ["havent"], "e": "El gerundi compost (havent + participi) indica anterioritat sense necessitat de nexe."},
      {"q": "Escriu el participi concordat: «La pregunta, l'he ___ perfectament.» (comprendre)", "a": ["compresa"], "e": "Comprendre té participi sigmàtic (comprés); amb l'acusatiu femení la, concorda: compresa."},
      {"q": "Escriu el participi concordat: «Eixes pel·lícules, les he ___ tres vegades.» (veure)", "a": ["vistes"], "e": "Veure → vist, vista; concordança amb les: vistes."},
      {"q": "Escriu el participi: «S'ha ___ el llum de l'escala.» (encendre)", "a": ["encés"], "e": "Encendre, acabat en -ndre, té participi sigmàtic: encés, encesa."},
      {"q": "Escriu el participi femení singular de «sorprendre».", "a": ["sorpresa"], "e": "Sorprendre té participi sigmàtic: sorprés, sorpresa."},
      {"q": "Escriu el gerundi de «escriure».", "a": ["escrivint"], "e": "Escriure fa escrivint (amb v, com escrivia)."},
      {"q": "Escriu el gerundi de «moure».", "a": ["movent"], "e": "Moure fa movent (com movia)."},
      {"q": "Escriu el gerundi de «jaure».", "a": ["jaient", "jaent"], "e": "Jaure admet jaient i jaent, com caure (caient, caent)."},
      {"q": "Escriu el gerundi de «ploure».", "a": ["plovent"], "e": "Ploure fa plovent (com plovia)."}
    ]
  },
  {
    "id": "c92452d0-6c86-5ccd-aa10-c4fd543fcf7b", "type": "c1_mor_concordanca_temporal", "sort_order": 19,
    "title": "Concordança temporal: condicionals, temporals i completives", "name": "Correlació de temps en les condicionals reals i irreals, les temporals amb quan, les completives i les formes en -ra, -ria i -ss",
    "content": "Concordança temporal: correlació de temps en les oracions condicionals reals, irreals i irreals de passat (Si haguera estudiat més, hauria aprovat. Si estudiara més, aprovaria. Si estudie més, aprovaré), en les temporals amb quan i altres conjuncions (Quan estudie, aprovaré), en les subordinades completives en subjuntiu (Vull que vingues / Volia que vinguera) i en l'estil indirecte, i ús de les formes en -ra, -ria i -ss segons la normativa (3.2.2).", "icon": "⏳", "color": "#FFF9C4",
    "exercises": [
      {"q": "«Si ___ més, hauria aprovat.» (estudiar, ell; irreal de passat)", "o": ["haguera estudiat (o hagués estudiat)", "hauria estudiat", "haja estudiat"], "e": "Irreal de passat: plusquamperfet de subjuntiu en la pròtasi i condicional perfet en l'apòdosi."},
      {"q": "«Si estudiara més, ___.» (aprovar, ell)", "o": ["aprovaria", "aprovarà", "aprove"], "e": "Irreal (present o futur): imperfet de subjuntiu en la pròtasi i condicional en l'apòdosi."},
      {"q": "Escriu el verb: «Si ___ (tindre, jo) temps, t'ajudaré.»", "a": ["tinc"], "e": "Condicional real: present d'indicatiu després de si i futur en la principal."},
      {"q": "«Si ___ demà, avisa'm.» (vindre, tu)", "o": ["vens", "vingues", "vindries"], "e": "Després de la conjunció si, en les condicionals reals, va el present d'indicatiu (vens), no el subjuntiu."},
      {"q": "«Si ho ___ tot, me n'aniria d'acampada amb els amics.» (aprovar, jo)", "o": ["aprovara (o aprovés)", "aprovaria", "aprovaré"], "e": "L'apòdosi en condicional (me n'aniria) demana imperfet de subjuntiu en la pròtasi: si ho aprovara."},
      {"q": "«Si ho haguera aprovat tot, me n'hauria anat d'acampada.» Quina classe de condicional és?", "o": ["irreal de passat", "real", "irreal de present"], "e": "Es refereix a una situació que no s'ha produït en el passat: plusquamperfet de subjuntiu + condicional perfet."},
      {"q": "Quina correlació és correcta?", "o": ["Si tinguera diners, viatjaria més.", "Si tindria diners, viatjaria més.", "Si tinga diners, viatjaria més."], "e": "El condicional va en l'apòdosi, no darrere de si; la pròtasi irreal porta imperfet de subjuntiu."},
      {"q": "Quina frase és correcta?", "o": ["Si estudiara més, aprovaria.", "Si estudiara més, aprovara.", "Si estudiaria més, aprovaria."], "e": "Les formes en -ra només conserven valor de condicional en l'auxiliar haver (haguera fet) i en usos fixats de ser (fora bo); en la resta, condicional en -ria."},
      {"q": "«Jo també ho ___ fet, si m'ho hagueren dit.» Quines formes admet la GNV?", "o": ["hauria o haguera", "només hauria", "només haguera"], "e": "L'auxiliar del condicional perfet pot adoptar formes en -ria o en -ra: hauria fet o haguera fet."},
      {"q": "«Si m'ho hagueres dit abans, t'___ pogut ajudar.»", "o": ["hauria (o haguera)", "havia", "haja"], "e": "Apòdosi d'una irreal de passat: condicional perfet, amb l'auxiliar hauria o haguera."},
      {"q": "Sobre «Si només parlàvem de la seua obra poètica, no donaríem una visió completa de l'autor», quina afirmació és correcta?", "o": ["És correcta però molt formal; l'estàndard preferix l'imperfet de subjuntiu (parlàrem).", "És incorrecta: l'imperfet d'indicatiu mai no pot aparéixer darrere de si.", "És la construcció preferida en la llengua estàndard."], "e": "L'imperfet d'indicatiu amb valor d'irrealitat és possible en la pròtasi, però se sent com a molt formal; es preferix el subjuntiu."},
      {"q": "«Si ___ veritat, no s'hauria excusat tant.» (ser)", "o": ["fora (o fos)", "seria", "serà"], "e": "Pròtasi irreal: imperfet de subjuntiu de ser (fora o fos)."},
      {"q": "«Si ___ vent, sempre tanquem les finestres.» (fer)", "o": ["fa", "faça", "farà"], "e": "Condicional amb valor habitual: present d'indicatiu en les dos oracions."},
      {"q": "«Posat que ___, farem festa.» (vindre, ell)", "o": ["vinga", "vindrà", "ve"], "e": "Les locucions condicionals posat que, en cas que, a condició que, sempre que (condicional)... van amb subjuntiu."},
      {"q": "«Ens deixaran entrar a condició que no ___ fotografies.» (fer, ell)", "o": ["faça", "fa", "farà"], "e": "A condició que + subjuntiu: a condició que no faça fotografies."},
      {"q": "«Quan ___ la faena, farem un viatge.» (acabar, nosaltres) Quines formes admet la GNV?", "o": ["acabem o acabarem", "només acabarem", "només acabàrem"], "e": "Amb quan i posterioritat a l'acte de parla alternen el present de subjuntiu (el més habitual hui) i el futur (l'ús més tradicional)."},
      {"q": "Segons la GNV, en «Quan arribarem a casa, sopareu», el futur després de quan és...", "o": ["correcte: és l'ús tradicional, tot i que hui és més habitual el subjuntiu (arribem)", "incorrecte: després de quan mai no pot anar futur", "obligatori: el subjuntiu no és possible"], "e": "La GNV accepta tots dos temps: el futur respon a l'ús més tradicional i el subjuntiu és la forma més habitual."},
      {"q": "«Quan ___ a València, anirem al museu.» (vindre, tu)", "o": ["vingues", "vingueres", "vindries"], "e": "Temporal referida al futur: present de subjuntiu (o futur), mai imperfet de subjuntiu ni condicional si la principal és un futur."},
      {"q": "Escriu el verb: «Així que ___ (arribar) Conxa, ens n'anirem.»", "a": ["arribe", "arribarà"], "e": "Conjuncions de posterioritat referides al futur (així que, tan prompte com, tan bon punt): present de subjuntiu (o futur, ús més tradicional)."},
      {"q": "«Tot seguit que en ___ coneixement, convocarem els socis.» (tindre, nosaltres)", "o": ["tinguem", "tinguérem", "tindríem"], "e": "Principal en futur + temporal de posterioritat → present de subjuntiu: tinguem."},
      {"q": "«Quan ___ bon temps, sempre sopem a la terrassa.» (fer)", "o": ["fa", "farà", "faria"], "e": "Si la temporal expressa un fet habitual, va en present d'indicatiu, igual que la principal."},
      {"q": "«Quan ___, preparaven el sopar.» (arribar, nosaltres)", "o": ["vam arribar (o arribàrem)", "arribem", "arribarem"], "e": "En el passat, l'imperfet (preparaven) indica simultaneïtat amb un fet passat expressat amb passat perifràstic o simple."},
      {"q": "«Abans que li ho ___, ja ho havia fet.» (demanar, jo)", "o": ["demanara (o demanés)", "demane", "demanaria"], "e": "Abans que + subjuntiu; amb una principal en passat, imperfet de subjuntiu."},
      {"q": "«Et faré companyia fins que ___ el teu fill.» (arribar)", "o": ["arribe", "arribara", "arribaria"], "e": "Principal en futur → present de subjuntiu en la temporal: fins que arribe."},
      {"q": "«Quan tu ___ anar al teatre, nosaltres ja hi haurem anat.» (voler)", "o": ["voldràs (o vullgues)", "voldries", "volies"], "e": "Posterioritat: futur o present de subjuntiu. El futur perfet (haurem anat) indica anterioritat respecte a eixe moment futur."},
      {"q": "«Li vaig dir que quan ___ els deures se'n vinguera a jugar.» (fer, ell)", "o": ["haguera fet (o hagués fet)", "ha fet", "haurà fet"], "e": "En un context de passat, l'anterioritat respecte a un fet posterior s'expressa amb el plusquamperfet de subjuntiu."},
      {"q": "Escriu el verb: «Vull que ho ___ (saber, tu) abans que ningú.»", "a": ["sàpies"], "e": "Verb de voluntat en present → present de subjuntiu en la completiva."},
      {"q": "«Volia que ___ l'endemà.» (tornar, nosaltres)", "o": ["tornàrem (o tornàssem, tornéssem)", "tornem", "tornaríem"], "e": "Verb de voluntat en passat → imperfet de subjuntiu (correlació de temps)."},
      {"q": "«Li molestava que ___ dormint.» (estar, ells)", "o": ["estigueren (o estiguessen)", "estiguen", "estarien"], "e": "Principal en passat (molestava) → imperfet de subjuntiu, amb valor simultani al passat."},
      {"q": "«És possible que ja se n'___ quan arribarem.» (anar, ells)", "o": ["hagen anat", "hagueren anat", "hauran anat"], "e": "El perfet de subjuntiu equival ací al futur perfet d'indicatiu: és possible que ja se n'hagen anat."},
      {"q": "«El preocupava que no li ___ res.» (dir, ells)", "o": ["hagueren dit (o haguessen dit)", "hauran dit", "han dit"], "e": "Verb de sentiment en passat + anterioritat → plusquamperfet de subjuntiu."},
      {"q": "«Va dir que era probable que ja se n'___ quan arribaríem.» (anar, ells)", "o": ["hagueren anat (o haguessen anat)", "hauran anat", "han anat"], "e": "En l'esfera del passat, el plusquamperfet de subjuntiu equival al condicional perfet: haurien anat → hagueren anat."},
      {"q": "«Els vam demanar que ___ la documentació.» (portar, ells)", "o": ["portaren (o portessen)", "portarien", "portaven"], "e": "Verb d'orde o petició en passat → imperfet de subjuntiu."},
      {"q": "«Espere que t'ho ___ molt bé.» (passar, tu)", "o": ["hages passat", "hagueres passat", "has passat"], "e": "Principal en present + fet anterior → perfet de subjuntiu."},
      {"q": "«Preguem als senyors viatgers ___ es dirigisquen al tren.»", "o": ["que", "(sense conjunció)", "de que"], "e": "Amb verbs de voluntat o desig, la conjunció que no s'elidix."},
      {"q": "«Ens va assegurar que l'endemà ___ la carta.» (enviar, ell)", "o": ["enviaria", "enviarà", "enviara"], "e": "Estil indirecte en passat: el condicional indica posterioritat en el passat."},
      {"q": "«Em va dir que no cridara tant, que el pare ___.» (dormir)", "o": ["dormia", "dormira", "dormiria"], "e": "L'imperfet d'indicatiu expressa simultaneïtat en el passat."},
      {"q": "En «Fora bo que es produïren canvis en la direcció», la forma fora equival a...", "o": ["seria", "era", "és"], "e": "Fora conserva el valor de condicional en alguns usos fixats: fora bo = seria bo."},
      {"q": "Quina forma d'imperfet de subjuntiu de «cantar» (ell) és també correcta, a més de cantara?", "o": ["cantés (o cantàs)", "cantaria", "cantava"], "e": "L'imperfet de subjuntiu admet formes en -ra i en -s; en la primera conjugació, cantés o cantàs."},
      {"q": "Escriu el plusquamperfet de subjuntiu (amb -ra): «Si ___ (saber, jo) que venies, t'hauria esperat.»", "a": ["haguera sabut", "hagués sabut"], "e": "Irreal de passat: plusquamperfet de subjuntiu en la pròtasi (també hagués sabut)."},
      {"q": "Escriu l'imperfet de subjuntiu: «Si ___ (poder, ella), ho faria hui mateix.»", "a": ["poguera", "pogués"], "e": "Irreal: imperfet de subjuntiu (poguera o pogués) + condicional."},
      {"q": "Escriu el verb: «Quan ___ (tindre, tu) els resultats, digues-m'ho.»", "a": ["tingues", "tindràs"], "e": "Temporal de futur: present de subjuntiu (tingues) o futur (tindràs), totes dues acceptades per la GNV."},
      {"q": "Escriu l'imperfet de subjuntiu: «Volíem que ens ___ (explicar, vosaltres) el projecte.»", "a": ["explicàreu", "explicàsseu", "explicésseu"], "e": "Principal en passat → imperfet de subjuntiu: explicàreu (o explicàsseu, explicésseu)."},
      {"q": "Escriu el condicional perfet: «Si m'ho hagueres dit, ho ___ (fer, jo).»", "a": ["hauria fet", "haguera fet"], "e": "Apòdosi irreal de passat: hauria fet o haguera fet."},
      {"q": "Escriu el verb: «Si ___ (ploure) demà, no anirem a la platja.»", "a": ["plou"], "e": "Condicional real: present d'indicatiu darrere de si."}
    ]
  }
]$data$::jsonb) AS t(
  id uuid, type text, sort_order smallint, title text, name text,
  content text, icon text, color text, exercises jsonb
);

INSERT INTO public.resources (id, name, type, category, content, difficulty, xp_earned, sort_order, metadata)
SELECT id, name, type, 'morfosintaxi', content, 'C1', 15, sort_order,
       jsonb_build_object('icon', icon, 'color', color, 'section_name', title)
FROM practice_catalog
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  type = EXCLUDED.type,
  category = EXCLUDED.category,
  content = EXCLUDED.content,
  difficulty = EXCLUDED.difficulty,
  xp_earned = EXCLUDED.xp_earned,
  sort_order = EXCLUDED.sort_order,
  -- Conserva la lliçó fixa («Aprendre lliçó»), si una migració posterior n'hi afig.
  metadata = EXCLUDED.metadata || jsonb_strip_nulls(jsonb_build_object('lesson', resources.metadata -> 'lesson'));

DELETE FROM public.practice_exercises e
USING practice_catalog c
WHERE e.resource_id = c.id AND e.level = 'C1';

INSERT INTO public.practice_exercises (resource_id, level, position, kind, prompt, options, answers, explanation)
SELECT c.id, 'C1', x.ord,
       CASE WHEN x.e ? 'a' THEN 'fill' ELSE 'choice' END,
       x.e->>'q',
       CASE WHEN x.e ? 'o' THEN ARRAY(SELECT jsonb_array_elements_text(x.e->'o')) END,
       CASE WHEN x.e ? 'a' THEN ARRAY(SELECT jsonb_array_elements_text(x.e->'a')) ELSE ARRAY[x.e->'o'->>0] END,
       x.e->>'e'
FROM practice_catalog c
CROSS JOIN LATERAL jsonb_array_elements(c.exercises) WITH ORDINALITY AS x(e, ord);

DROP TABLE practice_catalog;
